(function(A){Object.assign(A.D,{"G2842":{"l":"κοινωνία","o":19,"ar":"<f><o>κοινωνία</o>، <g>-ας, ἡ</g></f> <s n=\"1.\"><b>شركة</b>، <b>مشاركة، تواصل</b>: <r v=\"Acts.2.42\"></r>، <r v=\"2Cor.6.14\"></r>، <r v=\"Phil.1.5\"></r>؛ <g>τ. υἱοῦ</g> (شركة ابنه)، <r v=\"1Cor.1.9\"></r>؛ <g>τ. αἵματος, σώματος Χρ.</g> (شركة دم المسيح وجسده)، <r v=\"1Cor.10.16\"></r>؛ <g>παθημάτων αὐτσῦ</g> (شركة آلامه)، <r v=\"Phil.3.10\"></r>؛ <g>τ. πνεύματος</g> (شركة الروح)، <r v=\"2Cor.13.13\"></r>، <r v=\"Phil.2.1\"></r>؛ <g>δεξιὰς κοινωνίας</g> (يمين الشركة)، <r v=\"Gal.2.9\"></r>؛ <g>τ. πίστεώς σου</g> (شركة إيمانك)، <r v=\"Phlm.1.6\"></r>؛ يليه <g>μετὰ</g>: <g>τ. πατρός</g> (مع الآب)، <r v=\"1John.1.3\"></r>، <r v=\"1John.1.6\"></r>؛ <g>ἡμῶν, ἀλλήλων</g> (معنا، بعضنا مع بعض)، <r v=\"1John.1.3\"></r>، <r v=\"1John.1.7\"></r>.</s> <s n=\"2.\"><b>عطاء، إسهام، توزيع</b> (بوصفه ثمرة الشركة): <r v=\"Rom.15.26\"></r>، <r v=\"2Cor.8.4\"></r> <r v=\"2Cor.9.13\"></r>، <r v=\"Heb.13.6\"></r>.†</s>","en":"<f><o>κοινωνία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>κοινωνός</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Lev.6.2\"></r> (<r v=\"Lev.5.21\"></r>) (<h n=\"H3027\">יָד</h> <h n=\"H8667\">תְּשׂוּמֶת</h>), <r v=\"Wis.8.18\"></r>, <r v=\"3Macc.4.6\"></r>*;]</e> </et> <s n=\"1.\"><b>fellowship</b>, <b>communion</b>: <r v=\"Acts.2.42\"></r>, <r v=\"2Cor.6.14\"></r>, <r v=\"Phil.1.5\"></r>; <g>τ. υἱοῦ</g>, <r v=\"1Cor.1.9\"></r>; <g>τ. αἵματος, σώματος Χρ.</g>, <r v=\"1Cor.10.16\"></r>; <g>παθημάτων αὐτσῦ</g>, <r v=\"Phil.3.10\"></r>; <g>τ. πνεύματος</g>, <r v=\"2Cor.13.13\"></r>, <r v=\"Phil.2.1\"></r>; <g>δεξιὰς κοινωνίας</g>, <r v=\"Gal.2.9\"></r>; <g>τ. πίστεώς σου</g>, <r v=\"Phlm.1.6\"></r>; seq. <g>μετὰ</g>: <g>τ. πατρός</g>, <r v=\"1John.1.3\"></r>, <r v=\"1John.1.6\"></r>; <g>ἡμῶν, ἀλλήλων</g>, <r v=\"1John.1.3\"></r>, <r v=\"1John.1.7\"></r>.</s> <s n=\"2.\"><b>contribution</b> (as outcome of fellowship): <r v=\"Rom.15.26\"></r>, <r v=\"2Cor.8.4\"></r> <r v=\"2Cor.9.13\"></r>, <r v=\"Heb.13.6\"></r> (cf. Art. <i>Communion</i>, <i>DB</i>, i, 460 ff.; MM, <i>Exp.</i>, xv).†</s>"},"G2844":{"l":"κοινωνός","o":10,"ar":"<f><o>κοινωνός</o>، <g>-ή, -όν</g></f> <s n=\"1.\">صفةً، = <g>κοινός</g>.</s> <s n=\"2.\">اسمًا، <g>ὁ, ἡ κ.</g>، <s n=\"(a)\"><b>شريك</b>، <b>رفيق</b>، <b>صاحب</b>: <r v=\"2Cor.8.23\"></r>، <r v=\"Phlm.1.17\"></r>؛ مع قابل الشخص، <r v=\"Luke.5.10\"></r>؛ مع المضاف إليه للشخص، <r v=\"Heb.10.33\"></r>؛ والتعبير نفسه يليه <g>ἐν</g>، <r v=\"Matt.23.30\"></r>؛</s> <s n=\"(b)\"><b>شريك في</b>، <b>مُشارِك</b>: مع المضاف إليه للشيء، <r v=\"1Cor.10.18\"></r>، <r v=\"1Cor.10.20\"></r>، <r v=\"2Cor.1.7\"></r>، <r v=\"1Pet.5.1\"></r>، <r v=\"2Pet.1.4\"></r>.†</s> </s>","en":"<f><o>κοινωνός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>κοινός</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.28.24\"></r>, <r v=\"Isa.1.23\"></r> (<h n=\"H2270\">חָבֵר</h>), <r v=\"Mal.2.14\"></r> (<h n=\"H2278\">חֲבֶרֶת</h>), <r v=\"Ezra.8.13\"></r>, al.;]</e> </et> <s n=\"1.\">as adj., = <g>κοινός</g>.</s> <s n=\"2.\">As subst., <g>ὁ, ἡ κ.</g>, <s n=\"(a)\"><b>a partner</b>, <b>associate</b>, <b>companion</b>: <r v=\"2Cor.8.23\"></r>, <r v=\"Phlm.1.17\"></r>; c. dat. pers., <r v=\"Luke.5.10\"></r>; c. gen. pers., <r v=\"Heb.10.33\"></r>; id. seq. <g>ἐν</g>, <r v=\"Matt.23.30\"></r>;</s> <s n=\"(b)\"><b>a partaker</b>, <b>sharer</b>: c. gen. rei, <r v=\"1Cor.10.18\"></r>, <r v=\"1Cor.10.20\"></r>, <r v=\"2Cor.1.7\"></r>, <r v=\"1Pet.5.1\"></r>, <r v=\"2Pet.1.4\"></r> (v. Deiss., <i>BS</i>, 368 n<i>2</i>).†</s> </s>"},"G2820":{"l":"κληρόω","o":1,"ar":"<f><o>κληρόω</o>، <g>-ῶ</g>،</f> <s n=\"1.\"><b>يُلقي القُرعة</b>.</s> <s n=\"2.\"><b>يختار بالقُرعة</b>.</s> <s n=\"3.\"><b>يُعيِّن بالقُرعة</b>، <b>يُخصِّص نصيبًا</b>: المبني للمجهول، <g>ἐν ᾧ καὶ ἐκληρώθημεν</g>، <r v=\"Eph.1.11\"></r>.†</s>","en":"<f><o>κληρόω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"1Sam.14.41\"></r> (<h n=\"H3920\">לכד</h> ni.), <r v=\"Ezra.4.11\"></r> A (<h n=\"H7121\">קרא</h> ni.), <r v=\"Isa.17.11\"></r>*;]</e> </et> <s n=\"1.\"><b>to cast lots</b>.</s> <s n=\"2.\"><b>to choose by lot</b>.</s> <s n=\"3.\"><b>to assign by lot</b>, <b>assign a portion</b>: pass., <g>ἐν ᾧ καὶ ἐκληρώθημεν</g>, <r v=\"Eph.1.11\"></r> (on the various interpretations, v. <i>ICC</i>; AR; Ellic., in l.).†</s>"},"G2831":{"l":"κλυδωνίζομαι","o":1,"ar":"<f>† <o>κλυδωνίζομαι</o></f> <s><b>تتقاذفه الأمواج</b>؛ مجازيًا، <b>يضطرب كالأمواج</b>: <r v=\"Eph.4.14\"></r>.†</s>","en":"<f>† <o>κλυδωνίζομαι</o></f> <et> <e t=\"derivation\">(&lt; <g>κλύδων</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Isa.57.20\"></r> (<h n=\"H1644\">גּרשׁ</h>)*;]</e> </et> <s><b>to be tossed by waves</b>; metaph., <b>to be tossed like waves</b> (cf. FlJ, <i>Ant.</i>, ix, 11, 3): <r v=\"Eph.4.14\"></r>.†</s>"},"G2813":{"l":"κλέπτω","o":13,"ar":"<f><o>κλέπτω</o>،</f> <s><b>يسرق</b>: مطلقًا (بلا مفعول)، <r v=\"Matt.6.19\"></r>، <r v=\"Matt.6.20\"></r> <r v=\"Matt.19.18\"></r>، <r v=\"Mark.10.19\"></r>، <r v=\"Luke.18.20\"></r>، <r v=\"John.10.10\"></r>، <r v=\"Rom.2.21\"></r> <r v=\"Rom.13.9\"></r>، <r v=\"Eph.4.28\"></r>؛ مع المنصوب، <r v=\"Matt.27.64\"></r> <r v=\"Matt.28.13\"></r>.†</s>","en":"<f><o>κλέπτω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H1589\">גּנב</h>;]</e> </et> <s><b>to steal</b>: absol., <r v=\"Matt.6.19\"></r>, <r v=\"Matt.6.20\"></r> <r v=\"Matt.19.18\"></r>, <r v=\"Mark.10.19\"></r>, <r v=\"Luke.18.20\"></r>, <r v=\"John.10.10\"></r>, <r v=\"Rom.2.21\"></r> <r v=\"Rom.13.9\"></r>, <r v=\"Eph.4.28\"></r>; c. acc., <r v=\"Matt.27.64\"></r> <r v=\"Matt.28.13\"></r>.†</s>"},"G2821":{"l":"κλῆσις","o":11,"ar":"<f><o>κλῆσις</o>، <g>-εως, ἡ</g> (<g>καλέω</g>)،</f> <s><b>دعوة</b>، <b>نداء</b>؛ وفي العهد الجديد، دائمًا عن الدعوة الإلهية إلى الخلاص: <r v=\"Rom.11.29\"></r>، <r v=\"1Cor.1.26\"></r> <r v=\"1Cor.7.20\"></r>، <r v=\"Eph.1.18\"></r> <r v=\"Eph.4.1\"></r>، <r v=\"Eph.4.4\"></r>، <r v=\"Phil.3.14\"></r>، <r v=\"2Thess.1.11\"></r>، <r v=\"2Tim.1.9\"></r>، <r v=\"Heb.3.1\"></r>، <r v=\"2Pet.1.10\"></r>.†</s>","en":"<f><o>κλῆσις</o>, <g>-εως, ἡ</g> (<g>καλέω</g>),</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Jer.31.6\"></r> (<h n=\"H7121\">קרא</h>), <r v=\"Jdt.12.10\"></r> A, <r v=\"3Macc.5.14\"></r>*;]</e> </et> <s><b>a calling</b>, <b>call</b>; in NT, always of the Divine call to salvation: <r v=\"Rom.11.29\"></r>, <r v=\"1Cor.1.26\"></r> <r v=\"1Cor.7.20\"></r>, <r v=\"Eph.1.18\"></r> <r v=\"Eph.4.1\"></r>, <r v=\"Eph.4.4\"></r>, <r v=\"Phil.3.14\"></r>, <r v=\"2Thess.1.11\"></r>, <r v=\"2Tim.1.9\"></r>, <r v=\"Heb.3.1\"></r>, <r v=\"2Pet.1.10\"></r> (Cremer, 332).†</s>"},"G2872":{"l":"κοπιάω","o":23,"ar":"<f><o>κοπιάω</o>، <g>-ῶ</g></f> <s n=\"1.\"><b>يتعب</b> (يُعيي): <r v=\"Matt.11.28\"></r>، <r v=\"John.4.6\"></r>، <r v=\"Rev.2.3\"></r> (قارن <r v=\"Isa.40.31\"></r>).</s> <s n=\"2.\">ومن ثمّ، في السبعينية والعهد الجديد، <b>يعمل بجهد</b>، <b>يكدّ</b>: مطلقًا (بلا مفعول)، <r v=\"Matt.6.28\"></r>، <r v=\"Luke.5.5\"></r> <r v=\"Luke.12.27\"></r>، <r v=\"John.4.38\"></r>، <r v=\"Acts.20.35\"></r>، <r v=\"1Cor.4.12\"></r>، <r v=\"Eph.4.28\"></r>، <r v=\"2Tim.2.6\"></r>؛ مع منصوب الشيء، <r v=\"John.4.38\"></r>؛ كثيرًا في <i>رسائل بولس</i>، عن تعب الخدمة: <r v=\"1Cor.15.10\"></r> <r v=\"1Cor.16.16\"></r>؛ «يليه» <g>ἐν</g>، <r v=\"Rom.16.12\"></r>، <r v=\"1Thess.5.12\"></r>، <r v=\"1Tim.5.17\"></r>؛ <g>εἰς</g>، <r v=\"Rom.16.6\"></r>، <r v=\"Gal.4.11\"></r>، <r v=\"Phil.2.16\"></r>، <r v=\"Col.1.29\"></r>، <r v=\"1Tim.4.10\"></r>.†</s>","en":"<f><o>κοπιάω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>κόπος</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3021\">יגע</h>;]</e> </et> <s n=\"1.\">(as in cl.) <b>to grow weary</b>: <r v=\"Matt.11.28\"></r>, <r v=\"John.4.6\"></r>, <r v=\"Rev.2.3\"></r> (cf. <r v=\"Isa.40.31\"></r>).</s> <s n=\"2.\">Hence, in LXX and NT, <b>to work with effort</b>, <b>to toil</b>: absol., <r v=\"Matt.6.28\"></r>, <r v=\"Luke.5.5\"></r> <r v=\"Luke.12.27\"></r>, <r v=\"John.4.38\"></r>, <r v=\"Acts.20.35\"></r>, <r v=\"1Cor.4.12\"></r>, <r v=\"Eph.4.28\"></r>, <r v=\"2Tim.2.6\"></r>; c. acc. rei, <r v=\"John.4.38\"></r>; freq. in <i>Paul. Epp.</i>, of ministerial labour: <r v=\"1Cor.15.10\"></r> <r v=\"1Cor.16.16\"></r>; seq. <g>ἐν</g>, <r v=\"Rom.16.12\"></r>, <r v=\"1Thess.5.12\"></r> (v. M, <i>Th.</i>, in l.), <r v=\"1Tim.5.17\"></r>; <g>εἰς</g>, <r v=\"Rom.16.6\"></r>, <r v=\"Gal.4.11\"></r>, <r v=\"Phil.2.16\"></r>, <r v=\"Col.1.29\"></r>, <r v=\"1Tim.4.10\"></r>.†</s>"},"G2889":{"l":"κόσμος","o":186,"ar":"<f><o>κόσμος</o>، <g>-ου, ὁ</g></f> <s> <s n=\"1.\">في اليونانية الكلاسيكية: <b>نظام (ترتيب)</b> .</s> <s n=\"2.\"><b>حِلية</b>، <b>زينة</b>، خاصةً زينة النساء : <r v=\"1Pet.3.3\"></r>.</s> <s n=\"3.\">ولاحقًا، <b>العالم</b> أو <b>الكون</b>، بوصفه نظامًا مرتَّبًا : <r v=\"Acts.17.24\"></r>، <r v=\"Rom.4.13\"></r>، <r v=\"1Cor.3.22\"></r>، <r v=\"Phil.2.15\"></r>، <r v=\"Heb.4.3\"></r>، وفي مواضع أخرى.</s> <s n=\"4.\">عند الكتّاب المتأخرين فقط، <b>العالم</b>، أي <b>الأرض</b> (= <g>ἡ οἰκουμένη</g>، قارن <r v=\"Matt.4.8\"></r> مع <r v=\"Luke.4.5\"></r>): <r v=\"Matt.4.8\"></r>، <r v=\"Mark.16.15\"></r>، <r v=\"Col.2.20\"></r>، <r v=\"1Tim.6.7\"></r>، وفي مواضع أخرى؛ ومن ثمّ كنايةً، <s n=\"(a)\">عن سكان العالم من البشر: <r v=\"Matt.5.14\"></r> <r v=\"Matt.13.38\"></r>، <r v=\"Mark.14.9\"></r>، <r v=\"John.1.10\"></r> <r v=\"John.4.42\"></r> <r v=\"John.12.47\"></r>، <r v=\"Rom.3.6\"></r>، <r v=\"1Cor.4.13\"></r>، <r v=\"2Cor.5.19\"></r>، <r v=\"2Pet.2.5\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\">عن الشؤون أو المقتنيات الدنيوية: <r v=\"Matt.16.26\"></r>، <r v=\"Mark.8.36\"></r>، <r v=\"Luke.9.25\"></r>، <r v=\"1Cor.7.31\"></r>، <r v=\"1John.2.16\"></r>، وفي مواضع أخرى؛</s> <s n=\"(c)\">بالمعنى الأخلاقي، عن الأشرار (غير الأتقياء): <r v=\"John.7.7\"></r> <r v=\"John.14.17\"></r>، <r v=\"John.14.27\"></r>، <r v=\"1Cor.1.21\"></r>، <r v=\"Jas.1.27\"></r>، <r v=\"1John.4.4\"></r>، وفي مواضع أخرى؛</s> <s n=\"(d)\">مجازيًا: <g>ὁ κ. τῆς ἀδικίας</g>، <r v=\"Jas.3.6\"></r>.</s> </s> </s>","en":"<f><o>κόσμος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Gen.2.1\"></r>, <r v=\"Deut.4.19\"></r> <r v=\"Deut.17.3\"></r>, <r v=\"Isa.24.21\"></r> <r v=\"Isa.40.26\"></r> (<h n=\"H6633\">צבא</h>), <r v=\"Exod.33.5\"></r>, <r v=\"Exod.33.6\"></r>, <r v=\"Jer.2.32\"></r> <r v=\"Jer.4.30\"></r>, <r v=\"Ezek.7.20\"></r> <r v=\"Ezek.16.11\"></r> <r v=\"Ezek.23.40\"></r> (<h n=\"H5716\">עֲדִי</h>), <r v=\"Isa.61.10\"></r> (<h n=\"H3627\">כְּלִי</h>), al., <r v=\"Wis.2.24\"></r> and freq., <r v=\"Sir.6.30\"></r>, al;]</e> </et> <s> <s n=\"1.\"><b>order</b> (Hom., Plat., al.).</s> <s n=\"2.\"><b>ornament</b>, <b>adornment</b>, esp. of women (Hom., al.): <r v=\"1Pet.3.3\"></r>.</s> <s n=\"3.\">Later, the <b>world</b> or <b>universe</b>, as an ordered system (Plat., al.): <r v=\"Acts.17.24\"></r>, <r v=\"Rom.4.13\"></r>, <r v=\"1Cor.3.22\"></r>, <r v=\"Phil.2.15\"></r>, <r v=\"Heb.4.3\"></r>, al.</s> <s n=\"4.\">In late writers only, <b>the world</b>, i.e. <b>the earth</b> (= <g>ἡ οἰκουμένη</g>, cf. <r v=\"Matt.4.8\"></r> with <r v=\"Luke.4.5\"></r>): <r v=\"Matt.4.8\"></r>, <r v=\"Mark.16.15\"></r>, <r v=\"Col.2.20\"></r>, <r v=\"1Tim.6.7\"></r>, al.; hence by meton., <s n=\"(a)\">of the human inhabitants of the world: <r v=\"Matt.5.14\"></r> <r v=\"Matt.13.38\"></r>, <r v=\"Mark.14.9\"></r>, <r v=\"John.1.10\"></r> <r v=\"John.4.42\"></r> <r v=\"John.12.47\"></r>, <r v=\"Rom.3.6\"></r>, <r v=\"1Cor.4.13\"></r>, <r v=\"2Cor.5.19\"></r>, <r v=\"2Pet.2.5\"></r>, al.;</s> <s n=\"(b)\">of worldly affairs or possessions: <r v=\"Matt.16.26\"></r>, <r v=\"Mark.8.36\"></r>, <r v=\"Luke.9.25\"></r>, <r v=\"1Cor.7.31\"></r>, <r v=\"1John.2.16\"></r>, al.;</s> <s n=\"(c)\">in ethical sense, of the ungodly: <r v=\"John.7.7\"></r> <r v=\"John.14.17\"></r>, <r v=\"John.14.27\"></r>, <r v=\"1Cor.1.21\"></r>, <r v=\"Jas.1.27\"></r>, <r v=\"1John.4.4\"></r>, al.;</s> <s n=\"(d)\">metaph.: <g>ὁ κ. τῆς ἀδικίας</g>, <r v=\"Jas.3.6\"></r>.</s> </s> </s> <sy><i>SYN.</i>: <g>αἰών</g>, q.v. (cf . also Dalman, <i>Words</i>, 162 ff.; Tr., <i>Syn.</i>, § lix; Westc., additional note on <r v=\"John.1.10\"></r>; <i>DB</i>, iv, 938 ff.).</sy>"},"G2865":{"l":"κομίζω","o":10,"ar":"<f><o>κομίζω</o>،</f> <s n=\"1.\"><b>يعتني بـ</b>.</s> <s n=\"2.\"><b>يحمل (شيئًا) إلى برّ الأمان</b>.</s> <s n=\"3.\"><b>يحمل ويأخذ</b> غنيمةً.</s> <s n=\"4.\"><b>يحمل</b> أو <b>ينقل</b>: <r v=\"Luke.7.37\"></r>. الصيغة الوسطى، <b>يحمل لنفسه</b>، ومن ثمّ، <s n=\"(a)\"><b>ينال (يأخذ):</b> <r v=\"Heb.10.36\"></r> <r v=\"Heb.11.13\"></r>، <r v=\"Heb.11.39\"></r>، <r v=\"1Pet.1.9\"></r> <r v=\"1Pet.5.4\"></r>، <r v=\"2Pet.2.13\"></r>؛</s> <s n=\"(b)\"><b>يستردّ</b>، <b>يستعيد</b> : <r v=\"Matt.25.27\"></r>، <r v=\"Heb.11.19\"></r>؛ مجازيًا، عن المجازاة، <r v=\"2Cor.5.10\"></r>، <r v=\"Col.3.25\"></r>؛ <g>παρὰ Κυρίου</g>، <r v=\"Eph.6.8\"></r> (قارن <g>ἐκ-</g>، <g>συν-κομίζω</g>).†</s> </s>","en":"<f><o>κομίζω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5375\">נשׂא</h>, etc.;]</e> </et> <s n=\"1.\"><b>to take care of</b>.</s> <s n=\"2.\"><b>to carry off safe</b>.</s> <s n=\"3.\"><b>to carry off</b> as booty.</s> <s n=\"4.\"><b>to bear</b> or <b>carry</b>: <r v=\"Luke.7.37\"></r>. Mid., <b>to bear for oneself</b>, hence, <s n=\"(a)\"><b>to receive:</b> <r v=\"Heb.10.36\"></r> <r v=\"Heb.11.13\"></r>, <r v=\"Heb.11.39\"></r>, <r v=\"1Pet.1.9\"></r> <r v=\"1Pet.5.4\"></r>, <r v=\"2Pet.2.13\"></r>;</s> <s n=\"(b)\"><b>to receive back</b>, <b>recover</b> (in cl. so also act.): <r v=\"Matt.25.27\"></r>, <r v=\"Heb.11.19\"></r>; metaph., of requital, <r v=\"2Cor.5.10\"></r>, <r v=\"Col.3.25\"></r>; <g>παρὰ Κυρίου</g>, <r v=\"Eph.6.8\"></r> (cf. <g>ἐκ-</g>, <g>συν-κομίζω</g>).†</s> </s>"},"G2817":{"l":"κληρονομία","o":14,"ar":"<f><o>κληρονομία</o>، <g>-ας, ἡ</g></f> <s>أصلاً، <b>ملكٌ موروث</b>، <b>ميراث</b>: <r v=\"Matt.21.38\"></r>، <r v=\"Mark.12.7\"></r>، <r v=\"Luke.12.13\"></r> <r v=\"Luke.20.14\"></r>؛ وبوجه عام، <b>مُلْك (مقتنى)</b>، <b>ميراث</b>: <r v=\"Acts.7.5\"></r>، <r v=\"Heb.11.8\"></r>؛ عن الملكوت المسياني وبركاته، <r v=\"Acts.20.32\"></r>، <r v=\"Gal.3.18\"></r>، <r v=\"Col.3.24\"></r>، <r v=\"Eph.1.14\"></r>، <r v=\"Eph.1.18\"></r> <r v=\"Eph.5.5\"></r>، <r v=\"Heb.9.15\"></r>، <r v=\"1Pet.1.4\"></r>.†</s>","en":"<f><o>κληρονομία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>κληρονόμος</g>)</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5159\">נַחֲלָה</h>, also for <h n=\"H3425\">יְרֻשָּׁה</h>, etc.;]</e> </et> <s>prop., <b>an inherited property</b>, <b>an inheritance</b>: <r v=\"Matt.21.38\"></r>, <r v=\"Mark.12.7\"></r>, <r v=\"Luke.12.13\"></r> <r v=\"Luke.20.14\"></r>; in general, <b>a possession</b>, <b>inheritance</b>: <r v=\"Acts.7.5\"></r>, <r v=\"Heb.11.8\"></r>; of the Messianic Kingdom and its blessings, <r v=\"Acts.20.32\"></r>, <r v=\"Gal.3.18\"></r>, <r v=\"Col.3.24\"></r>, <r v=\"Eph.1.14\"></r>, <r v=\"Eph.1.18\"></r> <r v=\"Eph.5.5\"></r>, <r v=\"Heb.9.15\"></r>, <r v=\"1Pet.1.4\"></r>.†</s>"},"G2888":{"l":"κοσμοκράτωρ","o":1,"ar":"<f>*† <o>κοσμοκράτωρ</o>، <g>-ορος, ὁ</g></f> <s n=\"1.\">(قارن <r v=\"Eph.6.12\"></r>) <b>حاكم العالم كلّه</b> (وكذلك في الكتابات الربّانية: <h n=\"????\">קוֺזמוֺקְרָטוֺר</h>).</s> <s n=\"2.\"><b>حاكم هذا العالم</b> (في مقابل <g>παντοκράτωρ</g>): <g>οἱ κ. τ. σκότους τούτου</g>، <b>ولاة هذا العالم المظلم</b>، <r v=\"Eph.6.12\"></r>.†</s>","en":"<f>*† <o>κοσμοκράτωρ</o>, <g>-ορος, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>κόσμος</g>, <g>κρατέω</g>),</e> </et> <s n=\"1.\">in Orphic hymns, al. (v. AR, <r v=\"Eph.6.12\"></r>), <b>a ruler of the whole world</b> (and so in Rabbinic writings: <h n=\"????\">קוֺזמוֺקְרָטוֺר</h>).</s> <s n=\"2.\"><b>a ruler of this world</b> (in contrast to <g>παντοκράτωρ</g>): <g>οἱ κ. τ. σκότους τούτου</g>, <b>the rulers of this dark world</b>, <r v=\"Eph.6.12\"></r>.†</s>"},"G2836":{"l":"κοιλία","o":22,"ar":"<f><o>κοιλία</o>، <g>-ας, ἡ</g></f> <s n=\"1.\"><b>البطن</b> (المعدة أو الأمعاء أو كلاهما): <r v=\"Matt.12.40\"></r> <r v=\"Matt.15.17\"></r>، <r v=\"Mark.7.19\"></r>، <r v=\"Luke.15.16\"></r>، <r v=\"Rom.16.18\"></r>، <r v=\"1Cor.6.13\"></r>، <r v=\"Phil.3.19\"></r>، <r v=\"Rev.10.9\"></r>، <r v=\"Rev.10.10\"></r>.</s> <s n=\"2.\">(كما كثيرًا في السبعينية) <b>الرحم، البطن</b>: <r v=\"Luke.1.41\"></r>، <r v=\"Luke.1.42\"></r>، <r v=\"Luke.1.44\"></r> <r v=\"Luke.2.21\"></r> <r v=\"Luke.11.27\"></r> <r v=\"Luke.23.29\"></r>، <r v=\"John.3.4\"></r>؛ <g>ἐκ κ. μητρός</g> (قارن <r v=\"Ps.22.11\"></r>، <r v=\"Job.1.21\"></r>، وفي مواضع أخرى)، <r v=\"Matt.19.12\"></r>، <r v=\"Luke.1.15\"></r>، <r v=\"Acts.3.2\"></r> <r v=\"Acts.14.8\"></r>، <r v=\"Gal.1.15\"></r>.</s> <s n=\"3.\">مجازيًا (مثل العبرية <h n=\"H990\">בֶּטֶן</h>، قارن <r v=\"Job.15.35\"></r>، <r v=\"Prov.20.27\"></r>، <r v=\"Sir.19.12\"></r>)، عن <b>القلب</b> (الداخل): <r v=\"John.7.38\"></r>.†</s>","en":"<f><o>κοιλία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>κοῖλος</g>, <i>hollow</i>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H990\">בֶּטֶן</h>, <h n=\"H4578\">מֵעִים</h>, <h n=\"H7130\">קֶרֶב</h>, <r v=\"Deut.7.13\"></r>, <r v=\"2Sam.7.12\"></r>, <r v=\"Gen.41.21\"></r>, al.; also (<r v=\"Job.3.11\"></r> <r v=\"Job.10.18\"></r> <r v=\"Job.31.15\"></r> <r v=\"Job.38.8\"></r>) for <h n=\"H7358\">רֶחֶם</h>;]</e> </et> <s n=\"1.\"><b>the belly</b> (stomach or intestines or both): <r v=\"Matt.12.40\"></r> <r v=\"Matt.15.17\"></r>, <r v=\"Mark.7.19\"></r>, <r v=\"Luke.15.16\"></r>, <r v=\"Rom.16.18\"></r>, <r v=\"1Cor.6.13\"></r>, <r v=\"Phil.3.19\"></r>, <r v=\"Rev.10.9\"></r>, <r v=\"Rev.10.10\"></r>.</s> <s n=\"2.\">(As often in LXX) <b>the womb</b>: <r v=\"Luke.1.41\"></r>, <r v=\"Luke.1.42\"></r>, <r v=\"Luke.1.44\"></r> <r v=\"Luke.2.21\"></r> <r v=\"Luke.11.27\"></r> <r v=\"Luke.23.29\"></r>, <r v=\"John.3.4\"></r>; <g>ἐκ κ. μητρός</g> (cf. <r v=\"Ps.22.11\"></r>, <r v=\"Job.1.21\"></r>, al.), <r v=\"Matt.19.12\"></r>, <r v=\"Luke.1.15\"></r>, <r v=\"Acts.3.2\"></r> <r v=\"Acts.14.8\"></r>, <r v=\"Gal.1.15\"></r>.</s> <s n=\"3.\">Metaph. (as Heb. <h n=\"H990\">בֶּטֶן</h>, cf. <r v=\"Job.15.35\"></r>, <r v=\"Prov.20.27\"></r>, <r v=\"Sir.19.12\"></r>), of the <b>heart</b>: <r v=\"John.7.38\"></r>.†</s>"},"G2848":{"l":"κόκκος","o":7,"ar":"<f><o>κόκκος</o>، <g>-ου, ὁ</g>،</f> <s><b>حبّة</b>: <r v=\"Matt.13.31\"></r> <r v=\"Matt.17.20\"></r>، <r v=\"Mark.4.31\"></r>، <r v=\"Luke.13.19\"></r> <r v=\"Luke.17.6\"></r>، <r v=\"John.12.24\"></r>، <r v=\"1Cor.15.37\"></r>.†</s>","en":"<f><o>κόκκος</o>, <g>-ου, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Lam.4.5\"></r> B <h>א</h> R (<h n=\"H8438\">תּוֹלָע</h>), <r v=\"Sir.45.11\"></r>*;]</e> </et> <s><b>a grain</b>: <r v=\"Matt.13.31\"></r> <r v=\"Matt.17.20\"></r>, <r v=\"Mark.4.31\"></r>, <r v=\"Luke.13.19\"></r> <r v=\"Luke.17.6\"></r>, <r v=\"John.12.24\"></r>, <r v=\"1Cor.15.37\"></r>.†</s>"},"G2815":{"l":"Κλήμης","o":1,"ar":"<f><o>Κλήμης</o>، <g>-εντος, ὁ</g>،</f> <s><b>أكليمندس</b>: <r v=\"Phil.4.3\"></r>.†</s>","en":"<f><o>Κλήμης</o>, <g>-εντος, ὁ</g>,</f> <s><b>Clement</b>: <r v=\"Phil.4.3\"></r>.†</s>"},"G2887":{"l":"κόσμιος","o":2,"ar":"<f><o>κόσμιος</o>، <g>-ον</g> (وفي الكلاسيكية <g>-α, -ον</g>)،</f> <s><b>مرتَّب</b>، <b>لائق</b>، <b>محتشم</b>: <r v=\"1Tim.2.9\"></r> <r v=\"1Tim.3.2\"></r>.†</s>","en":"<f><o>κόσμιος</o>, <g>-ον</g> (in cl. <g>-α, -ον</g>),</f> <et> <e t=\"derivation\">(&lt; <g>κόσμος</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Eccl.12.9\"></r> (<h n=\"H8626\">תּקן</h>)*;]</e> </et> <s><b>orderly</b>, <b>decent</b>, <b>modest</b>: <r v=\"1Tim.2.9\"></r> (WH, mg., <g>-ίως</g>, q.v.) <r v=\"1Tim.3.2\"></r>.†</s>"},"G2833":{"l":"κνήθω","o":1,"ar":"<f>* <o>κνήθω</o></f> <s n=\"1.\"><b>يحكّ</b>.</s> <s n=\"2.\"><b>يُدغدغ</b>؛ المبني للمجهول: <b>يكون مستحكًّا</b>: <r v=\"2Tim.4.3\"></r>.†</s>","en":"<f>* <o>κνήθω</o></f> <et> <e t=\"derivation\">(late form of <g>κνάω</g>),</e> </et> <s n=\"1.\"><b>to scratch</b>.</s> <s n=\"2.\"><b>to tickle</b>; pass., <b>to itch</b>: <r v=\"2Tim.4.3\"></r>.†</s>"},"G2896":{"l":"κράζω","o":55,"ar":"<f><o>κράζω</o>،</f> وهو في الكلاسيكية شعري غالبًا، <s n=\"1.\">أصلاً لفظ محاكٍ للصوت، عن الغراب: <b>نعب</b>، ومن ثم عمومًا عن الصيحات غير الواضحة: <b>صرخ</b>، <b>صاح</b>: <r v=\"Mark.5.5\"></r>، <r v=\"Mark.9.26\"></r>، <r v=\"Mark.15.39\"></r>، <r v=\"Luke.9.39\"></r>، وفي مواضع أخرى؛ عن الصراخ طلبًا للنقمة (قارن <r v=\"Gen.4.10\"></r>): <r v=\"Jas.5.4\"></r>.</s> <s n=\"2.\"><b>صرخ</b>، <b>نادى</b> بصوت عظيم: مع منصوب الشيء: <r v=\"Acts.19.32\"></r>؛ يليه كلام مباشر: <r v=\"Mark.10.48\"></r>، <r v=\"Luke.18.39\"></r>، وفي مواضع أخرى؛ (<g>ἐν</g>) <g>φωνῇ μεγάλῃ</g>: <r v=\"Mark.5.7\"></r>، <r v=\"Rev.14.15\"></r>، وفي مواضع أخرى؛ <g>λέγων</g>: <r v=\"Matt.8.29\"></r>، وفي مواضع أخرى؛ عن التعليم العلني: <r v=\"John.1.15\"></r>، <r v=\"Rom.9.27\"></r>، وفي مواضع أخرى؛ عن الصلاة الملحّة (قارن <r v=\"Job.35.12\"></r>، <r v=\"Ps.3.5\"></r>، وفي مواضع أخرى): <r v=\"Rom.8.15\"></r>، <r v=\"Gal.4.6\"></r>؛ التام بمعنى المضارع (استعمال دارج): <r v=\"John.1.15\"></r>.</s>","en":"<f><o>κράζω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H2199\">זעק</h>, <h n=\"H6817\">צעק</h>, <h n=\"H7121\">קרא</h>, etc.;]</e> </et> in cl. chiefly poët., <s n=\"1.\">prop. onomatop., of the raven, <b>to croak</b>, hence generally, of inartic. cries, <b>to scream</b>, <b>cry out</b> (Æsch., al.): <r v=\"Mark.5.5\"></r> <r v=\"Mark.9.26\"></r> <r v=\"Mark.15.39\"></r> (Rec., R, mg.), <r v=\"Luke.9.39\"></r>, al.; of crying for vengeance (cf. <r v=\"Gen.4.10\"></r>), <r v=\"Jas.5.4\"></r>.</s> <s n=\"2.\"><b>to cry</b>, <b>call</b> <b>out</b> with a loud voice: c. acc. rei, <r v=\"Acts.19.32\"></r>; seq. orat. dir., <r v=\"Mark.10.48\"></r>, <r v=\"Luke.18.39\"></r>, al.; (<g>ἐν</g>) <g>φωνῇ μεγάλῃ</g>, <r v=\"Mark.5.7\"></r>, <r v=\"Rev.14.15\"></r>, al.; <g>λέγων</g>, <r v=\"Matt.8.29\"></r>, al.; of public teaching, <r v=\"John.1.15\"></r>, <r v=\"Rom.9.27\"></r>, al.; of importunate prayer (cf. <r v=\"Job.35.12\"></r>, <r v=\"Ps.3.5\"></r>, al.), <r v=\"Rom.8.15\"></r>, <r v=\"Gal.4.6\"></r>; pf. with pres. sense (vernac.; M, <i>Pr.</i>, 147), <r v=\"John.1.15\"></r>.</s> <sy><i>SYN.</i>: v.s. <g>βοάω</g>.</sy>"},"G2843":{"l":"κοινωνικός","o":1,"ar":"<f>* <o>κοινωνικός</o>، <g>-ή, -όν</g></f> <s n=\"1.\"><b>اجتماعي، أليف</b>.</s> <s n=\"2.\"><b>مستعد للمشاركة</b> أو <b>للعطاء</b>: <r v=\"1Tim.6.18\"></r>.†</s>","en":"<f>* <o>κοινωνικός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>κοινωνία</g>),</e> </et> <s n=\"1.\"><b>sociable</b>.</s> <s n=\"2.\"><b>ready to communicate</b> or <b>impart</b> (R, mg., <i>ready to sympathize</i>, v. Field, <i>Notes</i>, 213 f.): <r v=\"1Tim.6.18\"></r>.†</s>"},"G2841":{"l":"κοινωνέω","o":8,"ar":"<f><o>κοινωνέω</o>، <g>-ῶ</g>،</f> <s><b>كان له نصيب في</b>، <b>شارك</b> (في شيء) <b>مع</b> (أحد)، <b>اشترك في</b>: مع مضاف إليه الشيء (كما هو المعتاد، وهكذا في <r v=\"Prov.1.11\"></r>)، <r v=\"Heb.2.14\"></r>؛ مع قابل الشيء، <r v=\"Rom.12.13\"></r>، <r v=\"Rom.15.27\"></r>، <r v=\"1Tim.5.22\"></r>، <r v=\"1Pet.4.13\"></r>، <r v=\"2John.1.11\"></r>؛ مع قابل الشخص، يليه <g>εἰς</g>، <r v=\"Phil.4.15\"></r>؛ <g>ἐν</g>، <r v=\"Gal.6.6\"></r> (قارن <g>συν-κοινωνέω</g>).†</s>","en":"<f><o>κοινωνέω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Chr.20.35\"></r>, <r v=\"Job.34.8\"></r>, <r v=\"Eccl.9.4\"></r> (<h n=\"H2266\">חבר</h>), <r v=\"Prov.1.11\"></r>, <r v=\"Wis.6.23\"></r>, <r v=\"Sir.13.1\"></r>, al.;]</e> </et> <s><b>to have a share of</b>, <b>go shares in</b> (something) <b>with</b> (some one), <b>take part in</b>: c. gen. rei (as usually in cl., so <r v=\"Prov.1.11\"></r>), <r v=\"Heb.2.14\"></r>; c. dat. rei, <r v=\"Rom.12.13\"></r> <r v=\"Rom.15.27\"></r>, <r v=\"1Tim.5.22\"></r>, <r v=\"1Pet.4.13\"></r>, <r v=\"2John.1.11\"></r>; c. dat. pers., seq. <g>εἰς</g>, <r v=\"Phil.4.15\"></r>; <g>ἐν</g>, <r v=\"Gal.6.6\"></r> (cf. <g>συν-κοινωνέω</g>).†</s>"},"G2886":{"l":"κοσμικός","o":2,"ar":"<f>* <o>κοσμικός</o>، <g>-ή, -όν</g></f> <s n=\"1.\"><b>متعلّق بالعالم</b> أو <b>الكون</b>.</s> <s n=\"2.\"><b>من هذا العالم</b>، <b>أرضي</b>. <r v=\"Heb.9.1\"></r>.</s> <s n=\"3.\">بالمعنى الأخلاقي: <b>عالمي، دنيوي</b>: <g>ἐπιθυμίαι</g>، <r v=\"Titus.2.12\"></r>.†</s>","en":"<f>* <o>κοσμικός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(<g>κόσμος</g>),</e> </et> <s n=\"1.\"><b>pertaining to the world</b> or <b>universe</b>.</s> <s n=\"2.\"><b>of this world</b>, <b>earthly</b>. <r v=\"Heb.9.1\"></r>.</s> <s n=\"3.\">In ethical sense, <b>worldly</b>: <g>ἐπιθυμίαι</g>, <r v=\"Titus.2.12\"></r>.†</s>"},"G2803":{"l":"Κλαυδία","o":1,"ar":"<f><o>Κλαυδία</o>، <g>-ας, ἡ</g>،</f> <s><b>كلافدية</b>: <r v=\"2Tim.4.21\"></r>.†</s>","en":"<f><o>Κλαυδία</o>, <g>-ας, ἡ</g>,</f> <s><b>Claudia</b>: <r v=\"2Tim.4.21\"></r>.†</s>"},"G2885":{"l":"κοσμέω","o":10,"ar":"<f><o>κοσμέω</o>، <g>-ῶ</g></f> <s n=\"1.\"><b>رتّب</b>، <b>نظّم</b>، <b>أعدّ، هيّأ</b>: <r v=\"Matt.25.7\"></r> (قارن <r v=\"Sir.50.9\"></r>، وفي مواضع أخرى).</s> <s n=\"2.\"><b>زيّن</b>، <b>جهّز، فرش</b>: <g>οἶκον</g>، المبني للمجهول، <r v=\"Matt.12.44\"></r>، <r v=\"Luke.11.25\"></r>؛ <g>μνημεῖα</g>، <r v=\"Matt.23.29\"></r>؛ <g>τὸ ἱερόν</g>، المبني للمجهول، <r v=\"Luke.21.5\"></r>؛ <g>θεμέλιοι</g>، <r v=\"Rev.21.19\"></r>؛ <g>νύμφην</g>، المبني للمجهول، <r v=\"Rev.21.2\"></r>؛ <g>ἑαυτάς</g>، يليه <g>ἐν</g>، <r v=\"1Tim.2.9\"></r>. مجازيًا، مع المنصوب للشخص، <r v=\"1Pet.3.5\"></r>؛ مع المنصوب للشيء، <r v=\"Titus.2.10\"></r>.†</s>","en":"<f><o>κοσμέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>κόσμος</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H5710\">עדה</h>, <h n=\"H8626\">תּקן</h>, etc.;]</e> </et> <s n=\"1.\"><b>to order</b>, <b>arrange</b>, <b>prepare</b> (in Hom. esp. of marshalling armies): <r v=\"Matt.25.7\"></r> (cf. <r v=\"Sir.50.9\"></r>, al.).</s> <s n=\"2.\"><b>to adorn</b>, <b>furnish</b>: <g>οἶκον</g>, pass., <r v=\"Matt.12.44\"></r>, <r v=\"Luke.11.25\"></r>; <g>μνημεῖα</g>, <r v=\"Matt.23.29\"></r>; <g>τὸ ἱερόν</g>, pass., <r v=\"Luke.21.5\"></r>; <g>θεμέλιοι</g>, <r v=\"Rev.21.19\"></r>; <g>νύμφην</g>, pass., <r v=\"Rev.21.2\"></r>; <g>ἑαυτάς</g>, seq. <g>ἐν</g>, <r v=\"1Tim.2.9\"></r>. Metaph., c. acc. pers., <r v=\"1Pet.3.5\"></r>; c. acc. rei, <r v=\"Titus.2.10\"></r>.†</s>"},"G2806":{"l":"κλάω","o":14,"ar":"<f><o>κλάω</o>،</f> <s><b>كسر</b>، <b>كسّر قطعًا</b>: عن الخبز، <r v=\"Matt.14.19\"></r> <r v=\"Matt.15.36\"></r> <r v=\"Matt.26.26\"></r>، <r v=\"Mark.8.6\"></r> <r v=\"Mark.14.22\"></r>، <r v=\"Luke.22.19\"></r> <r v=\"Luke.24.30\"></r>، <r v=\"Acts.2.46\"></r> <r v=\"Acts.20.7\"></r>، <r v=\"Acts.20.11\"></r> <r v=\"Acts.27.35\"></r>، <r v=\"1Cor.10.16\"></r> <r v=\"1Cor.11.24\"></r>؛ يليه <g>εἰς</g> مع المنصوب للشخص، <r v=\"Mark.8.19\"></r> (قارن <g>ἐκ-</g>، <g>κατα-κλάω</g>).†</s>","en":"<f><o>κλάω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Jer.16.7\"></r> (<h n=\"H6533\">פּרם</h>), al.;]</e> </et> <s><b>to break</b>, <b>break in pieces</b>: of bread, <r v=\"Matt.14.19\"></r> <r v=\"Matt.15.36\"></r> <r v=\"Matt.26.26\"></r>, <r v=\"Mark.8.6\"></r> <r v=\"Mark.14.22\"></r>, <r v=\"Luke.22.19\"></r> <r v=\"Luke.24.30\"></r>, <r v=\"Acts.2.46\"></r> <r v=\"Acts.20.7\"></r>, <r v=\"Acts.20.11\"></r> <r v=\"Acts.27.35\"></r>, <r v=\"1Cor.10.16\"></r> <r v=\"1Cor.11.24\"></r>; seq. <g>εἰς</g>, c. acc. pers., <r v=\"Mark.8.19\"></r> (cf. <g>ἐκ-</g>, <g>κατα-κλάω</g>).†</s>"},"G2863":{"l":"κομάω","o":2,"ar":"<f>* <o>κομάω</o>، <g>-ῶ</g></f> <s><b>أرخى شعره (أطاله)</b>: <r v=\"1Cor.11.14\"></r>، <r v=\"1Cor.11.15\"></r>.†</s>","en":"<f>* <o>κομάω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>κόμη</g>),</e> </et> <s><b>to wear long hair</b>: <r v=\"1Cor.11.14\"></r>, <r v=\"1Cor.11.15\"></r>.†</s>"},"G2822":{"l":"κλητός","o":10,"ar":"<f><o>κλητός</o>، <g>-ή, -όν</g></f> <s><b>مدعوّ</b>، <b>مَدعوّ إلى وليمة</b> (قارن <r v=\"1Sam.1.41\"></r>، <r v=\"3Macc.5.14\"></r>)؛ وفي العهد الجديد دائمًا عن الدعوة الإلهية؛ <s n=\"(a)\">إلى وظيفة ما: <g>κ. ἀπόστολος</g> (رسول مدعوّ)، <r v=\"Rom.1.1\"></r>، <r v=\"1Cor.1.1\"></r>؛</s> <s n=\"(b)\">إلى الخلاص: <r v=\"Rom.8.28\"></r>، <r v=\"1Cor.1.24\"></r>، <r v=\"Jude.1.1\"></r>؛ <g>κ. καὶ ἐκλεκτοὶ κ. πιστοί</g> (مدعوون ومختارون ومؤمنون)، <r v=\"Rev.17.14\"></r>؛ في الأناجيل (انظر تحت مدخل <g>καλέω</g>) يُميَّز عن <g>ἐκλεκτός</g>، <r v=\"Matt.20.16\"></r>، <r v=\"Matt.22.14\"></r>؛ <g>κ. Ἰησοῦ Χρ.</g> (مدعوّو يسوع المسيح)، <r v=\"Rom.1.6\"></r>؛ <g>κ. ἅγιοι</g>، <b>مدعوون قديسين</b>، <r v=\"Rom.1.7\"></r>، <r v=\"1Cor.1.2\"></r>.†</s> </s>","en":"<f><o>κλητός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>καλέω</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H7121\">קרא</h>, <h n=\"H4744\">מִקְרָא</h>, <r v=\"Exod.12.16\"></r>, al.;]</e> </et> <s><b>called</b>, <b>invited</b> (as to a banquet, Æsch., <r v=\"1Sam.1.41\"></r>, <r v=\"3Macc.5.14\"></r>); in NT, always of the Divine call; <s n=\"(a)\">to some office: <g>κ. ἀπόστολος</g>, <r v=\"Rom.1.1\"></r>, <r v=\"1Cor.1.1\"></r>;</s> <s n=\"(b)\">to salvation: <r v=\"Rom.8.28\"></r>, <r v=\"1Cor.1.24\"></r>, <r v=\"Jude.1.1\"></r>; <g>κ. καὶ ἐκλεκτοὶ κ. πιστοί</g>, <r v=\"Rev.17.14\"></r>; in gosp. (not in pl., v.s. <g>καλέω</g>) disting. fr.<g>ἐκλεκτός</g>, <r v=\"Matt.20.16\"></r> (WH, txt., R, omit), <r v=\"Matt.22.14\"></r>; <g>κ. Ἰησοῦ Χρ.</g>, <r v=\"Rom.1.6\"></r>; <g>κ. ἅγιοι</g>, <b>saints by calling</b>, <r v=\"Rom.1.7\"></r>, <r v=\"1Cor.1.2\"></r>.†</s> </s>"},"G2882":{"l":"Κόρινθος","o":6,"ar":"<f><o>Κόρινθος</o>، <g>-ου, ἡ</g>،</f> <s><b>كورنثوس</b>: <r v=\"Acts.18.1\"></r>، <r v=\"Acts.18.27\"></r> <r v=\"Acts.19.1\"></r>، <r v=\"1Cor.1.2\"></r>، <r v=\"2Cor.1.1\"></r>، <r v=\"2Cor.1.23\"></r>، <r v=\"2Tim.4.20\"></r>.†</s>","en":"<f><o>Κόρινθος</o>, <g>-ου, ἡ</g>,</f> <s><b>Corinth</b>: <r v=\"Acts.18.1\"></r>, <r v=\"Acts.18.27\"></r> <r v=\"Acts.19.1\"></r>, <r v=\"1Cor.1.2\"></r>, <r v=\"2Cor.1.1\"></r>, <r v=\"2Cor.1.23\"></r>, <r v=\"2Tim.4.20\"></r>.†</s>"},"G2853":{"l":"κολλάω","o":12,"ar":"<f><o>κολλάω</o>، <g>-ῶ</g></f> <s n=\"1.\"><b>يُلصق أو يلحم معًا</b>.</s> <s n=\"2.\">عمومًا: <b>يوحّد</b>، <b>يربط بإحكام</b>. في المبني للمجهول: <b>يلتصق بـ</b>، <b>ينضمّ</b> (إلى): مع القابل للشخص، <r v=\"Matt.19.5\"></r> <i>(السبعينية)</i>، <r v=\"Luke.10.11\"></r>، <r v=\"Luke.15.15\"></r>، <r v=\"Acts.5.13\"></r>، <r v=\"Acts.9.26\"></r>، <r v=\"Acts.10.28\"></r>، <r v=\"Acts.17.34\"></r>؛ <g>τ. πόρνῃ</g>، <r v=\"1Cor.6.16\"></r>؛ <g>τ. Κυρίῳ</g>، <r v=\"1Cor.6.17\"></r>؛ مع القابل للشيء، <g>ἅρματι</g>، <r v=\"Acts.8.29\"></r>؛ <g>τ. ἀγαθῴ</g>، <r v=\"Rom.12.9\"></r>؛ عن الخطايا المتراكمة معًا، <g>ἄχρι τ. οὐρανοῦ</g>، <r v=\"Rev.18.5\"></r>؛ عن الغبار، <r v=\"Luke.10.11\"></r> (قارن <g>τροσ-κολλάω</g>).†</s>","en":"<f><o>κολλάω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>κόλλα</g>, <i>glue</i>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1692\">דּבק</h>;]</e> </et> <s n=\"1.\"><b>to glue or cement together</b>.</s> <s n=\"2.\">Generally, <b>to unite</b>, <b>to join firmly</b>. Pass., <b>to cleave to</b>, <b>join</b> (oneself to): c. dat. pers., <r v=\"Matt.19.5\"></r><i>(LXX)</i>, <r v=\"Luke.10.11\"></r> <r v=\"Luke.15.15\"></r>, <r v=\"Acts.5.13\"></r> (but v. Field, <i>Notes</i>, 118) <r v=\"Acts.9.26\"></r> <r v=\"Acts.10.28\"></r> (v. Field, 118) <r v=\"Acts.17.34\"></r>; <g>τ. πόρνῃ</g>, <r v=\"1Cor.6.16\"></r>; <g>τ. Κυρίῳ</g>, <r v=\"1Cor.6.17\"></r>; c. dat. rei, <g>ἅρματι</g>, <r v=\"Acts.8.29\"></r>; <g>τ. ἀγαθῴ</g>, <r v=\"Rom.12.9\"></r>; of sins joining together, <g>ἄχρι τ. οὐρανοῦ</g>, <r v=\"Rev.18.5\"></r>, of dust, <r v=\"Luke.10.11\"></r> (cf. <g>τροσ-κολλάω</g>).†</s>"},"G2845":{"l":"κοίτη","o":4,"ar":"<f><o>κοίτη</o>، <g>-ης, ἡ</g>،</f> <s><b>فراش</b>: <r v=\"Luke.11.7\"></r>؛ وخاصةً <b>فراش الزوجية</b>: <g>κ. ἀμίαντος</g>، <r v=\"Heb.13.4\"></r>؛ <g>κ. ἔχειν</g>، عن المرأة الحامل، <r v=\"Rom.9.10\"></r> (قارن عبارات خاصة في السبعينية، <r v=\"Lev.15.18\"></r>، وفي مواضع أخرى)؛ عن العلاقات غير المشروعة، في الجمع، <r v=\"Rom.13.13\"></r>.†</s>","en":"<f><o>κοίτη</o>, <g>-ης, ἡ</g> (in Hom., <g>κοῖτος</g>),</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4904\">מִשְׁכָּב</h>, also for <h n=\"H7902\">שְׁכָבָה</h>, etc.;]</e> </et> <s><b>a bed</b>: <r v=\"Luke.11.7\"></r>; esp. <b>the marriage-bed</b>: <g>κ. ἀμίαντος</g>, <r v=\"Heb.13.4\"></r>; <g>κ. ἔχειν</g>, of a woman conceiving, <r v=\"Rom.9.10\"></r> (cf. peculiar phrases in LXX, <r v=\"Lev.15.18\"></r>, al.); of illicit intercourse, pl., <r v=\"Rom.13.13\"></r>.†</s>"},"G2816":{"l":"κληρονομέω","o":18,"ar":"<f><o>κληρονομέω</o>، <g>-ῶ</g></f> <s n=\"1.\"><b>ينال بالقرعة</b>.</s> <s n=\"2.\"><b>يرث</b>: مطلقًا، <r v=\"Gal.4.30\"></r><i>(السبعينية)</i>؛ وبوجه عام: <b>يقتني</b>، <b>يأخذ ملكًا له</b>، <b>ينال</b> (كما في <r v=\"Deut.4.5\"></r>، وفي مواضع أخرى، قارن <r v=\"Ps.25.3\"></r>، <r v=\"Isa.61.7\"></r>): مع المنصوب للشيء (كما في اليونانية المتأخرة عمومًا)، عن الملكوت المسياني (قارن <r v=\"Ps.37.11\"></r>، <r v=\"Sir.4.13\"></r> <r v=\"Sir.37.26\"></r>) وبركاته وامتيازاته، <g>τ. γῆν</g>، <r v=\"Matt.5.5\"></r><i>(قارن السبعينية)</i>؛ <g>τ. βασιλείαν</g>، <g>β. θεοῦ</g>، <r v=\"Matt.25.34\"></r>، <r v=\"1Cor.6.9\"></r>، <r v=\"1Cor.6.10\"></r> <r v=\"1Cor.15.50\"></r>، <r v=\"Gal.5.21\"></r>؛ <g>ζωὴν αἰώνιον</g>، <r v=\"Matt.19.29\"></r>، <r v=\"Mark.10.17\"></r>، <r v=\"Luke.10.25\"></r> <r v=\"Luke.18.18\"></r>؛ <g>σωτηρίαν</g>، <r v=\"Heb.1.14\"></r>؛ <g>τ. ἐπαγγελίας</g>، <r v=\"Heb.6.12\"></r>؛ <g>ἀφθαρσίαν</g>، <r v=\"1Cor.15.50\"></r>؛ <g>ὄνομα</g>، <r v=\"Heb.1.4\"></r>؛ <g>τ. εὐλογίαν</g>، <r v=\"Heb.12.17\"></r>، <r v=\"1Pet.3.9\"></r>؛ <g>ταῦτα</g>، <r v=\"Rev.21.7\"></r> (قارن <g>κατα-κληρονομέω</g>).†</s>","en":"<f><o>κληρονομέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>κληρονόμος</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3423\">ירשׁ</h>, also for <h n=\"H5157\">נחל</h>, etc.;]</e> </et> <s n=\"1.\"><b>to receive by lot</b>.</s> <s n=\"2.\"><b>to inherit</b> (in cl., usually c. gen. rei): absol., <r v=\"Gal.4.30\"></r><i>(LXX)</i>; in general, <b>to possess oneself of</b>, <b>receive as one's own</b>, <b>obtain</b> (as <r v=\"Deut.4.5\"></r>, al., cf. <r v=\"Ps.25.3\"></r>, <r v=\"Isa.61.7\"></r>): c. acc. rei (as generally in late Gk., v. M, <i>Pr.</i>, 65), of the Messianic Kingdom (cf. <r v=\"Ps.37.11\"></r>, <r v=\"Sir.4.13\"></r> <r v=\"Sir.37.26\"></r>, and v. Dalman, <i>Words</i>, 125 ff.) and its blessings and privileges, <g>τ. γῆν</g>, <r v=\"Matt.5.5\"></r><i>(cf. LXX)</i>; <g>τ. βασιλείαν</g>, <g>β. θεοῦ</g>, <r v=\"Matt.25.34\"></r>, <r v=\"1Cor.6.9\"></r>, <r v=\"1Cor.6.10\"></r> <r v=\"1Cor.15.50\"></r>, <r v=\"Gal.5.21\"></r>; <g>ζωὴν αἰώνιον</g>, <r v=\"Matt.19.29\"></r>, <r v=\"Mark.10.17\"></r>, <r v=\"Luke.10.25\"></r> <r v=\"Luke.18.18\"></r>; <g>σωτηρίαν</g>, <r v=\"Heb.1.14\"></r>; <g>τ. ἐπαγγελίας</g>, <r v=\"Heb.6.12\"></r>; <g>ἀφθαρσίαν</g>, <r v=\"1Cor.15.50\"></r>; <g>ὄνομα</g>, <r v=\"Heb.1.4\"></r>; <g>τ. εὐλογίαν</g>, <r v=\"Heb.12.17\"></r>, <r v=\"1Pet.3.9\"></r>; <g>ταῦτα</g>, <r v=\"Rev.21.7\"></r> (cf. <g>κατα-κληρονομέω</g>).†</s>"},"G2818":{"l":"κληρονόμος","o":15,"ar":"<f><o>κληρο-νόμος</o>، <g>-ου, ὁ</g></f> <s n=\"1.\"><b>وارث</b>: <r v=\"Matt.21.38\"></r>، <r v=\"Mark.12.7\"></r>، <r v=\"Luke.20.14\"></r>، <r v=\"Gal.4.1\"></r>؛ عن الذين يرثون، بوصفهم أبناء الله، امتيازات الملكوت المسياني؛ عن المسيح نفسه، <r v=\"Heb.1.2\"></r>؛ عن إبراهيم، <r v=\"Rom.4.13\"></r>، <r v=\"Rom.4.14\"></r>؛ عن المسيحيين، <r v=\"Rom.8.17\"></r>، <r v=\"Gal.3.29\"></r>، <r v=\"Titus.3.7\"></r>، <r v=\"Jas.2.5\"></r>.</s> <s n=\"2.\">(كما في السبعينية: <r v=\"Judg.18.7\"></r>، <r v=\"Mic.1.15\"></r>، <r v=\"Jer.8.10\"></r>) <b>مالك، صاحب</b>: <r v=\"Heb.6.17\"></r> <r v=\"Heb.11.7\"></r>.†</s>","en":"<f><o>κληρο-νόμος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>κλῆρος</g>, <g>νέμομαι</g>, <i>to possess</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Judg.18.7\"></r>, <r v=\"2Sam.14.7\"></r>, <r v=\"Mic.1.15\"></r>, <r v=\"Jer.8.10\"></r> (<h n=\"H3423\">יוֹרֵשׁ</h>), <r v=\"Sir.23.22\"></r>*;]</e> </et> <s n=\"1.\">(as in cl.) <b>an heir</b>: <r v=\"Matt.21.38\"></r>, <r v=\"Mark.12.7\"></r>, <r v=\"Luke.20.14\"></r>, <r v=\"Gal.4.1\"></r>; of those who as sons of God inherit the privileges of the Messianic Kingdom; of Christ himself, <r v=\"Heb.1.2\"></r>; of Abraham, <r v=\"Rom.4.13\"></r>, <r v=\"Rom.4.14\"></r>; of Christians, <r v=\"Rom.8.17\"></r>, <r v=\"Gal.3.29\"></r>, <r v=\"Titus.3.7\"></r>, <r v=\"Jas.2.5\"></r>.</s> <s n=\"2.\">(As in LXX: <r v=\"Judg.18.7\"></r>, <r v=\"Mic.1.15\"></r>, <r v=\"Jer.8.10\"></r>) <b>a possessor</b>: <r v=\"Heb.6.17\"></r> <r v=\"Heb.11.7\"></r> (Cremer, 359 f.).†</s>"},"G2819":{"l":"κλῆρος","o":11,"ar":"<f><o>κλῆρος</o>، <g>-ου, ὁ</g>،</f> <s><b>قرعة</b>؛ <s n=\"(a)\">ما يُلقى أو يُسحب: <r v=\"Matt.27.35\"></r>، <r v=\"Mark.15.24\"></r>، <r v=\"Luke.23.34\"></r>، <r v=\"John.19.24\"></r><i>(السبعينية)</i>، <r v=\"Acts.1.26\"></r>؛</s> <s n=\"(b)\">ما يُنال بالقرعة، <b>نصيب</b>: <r v=\"Acts.1.17\"></r> <r v=\"Acts.8.21\"></r>؛ عن نصيب في ملكوت الله (قارن <r v=\"Wis.5.5\"></r>)، <r v=\"Acts.26.18\"></r>، <r v=\"Col.1.12\"></r>؛ وفي الجمع عن الرعية الموكولة إلى الشيخ، <r v=\"1Pet.5.3\"></r>.†</s> </s>","en":"<f><o>κλῆρος</o>, <g>-ου, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5159\">נַחֲלָה</h>, <h n=\"H1486\">גּוֹרָל</h>;]</e> </et> <s><b>a lot</b>; <s n=\"(a)\">that which is cast or drawn: <r v=\"Matt.27.35\"></r>, <r v=\"Mark.15.24\"></r>, <r v=\"Luke.23.34\"></r>, <r v=\"John.19.24\"></r><i>(LXX)</i>, <r v=\"Acts.1.26\"></r>;</s> <s n=\"(b)\">that which is obtained by casting: <r v=\"Acts.1.17\"></r> <r v=\"Acts.8.21\"></r>; of a part in the Kingdom of God (cf. <r v=\"Wis.5.5\"></r>), <r v=\"Acts.26.18\"></r>, <r v=\"Col.1.12\"></r>; pl. of the \"cure\" of a presbyter, <r v=\"1Pet.5.3\"></r> (v. <i>ICC</i>, in l.).†</s> </s>"},"G2812":{"l":"κλέπτης","o":16,"ar":"<f><o>κλέπτης</o>، <g>-ου, ὁ</g>،</f> <s><b>سارق، لص</b>: <r v=\"Matt.6.19\"></r>، <r v=\"Matt.6.20\"></r>، <r v=\"Matt.24.43\"></r>، <r v=\"Luke.12.33\"></r>، <r v=\"Luke.12.39\"></r>، <r v=\"John.10.1\"></r>، <r v=\"John.10.10\"></r>، <r v=\"John.12.6\"></r>، <r v=\"1Cor.6.10\"></r>، <r v=\"1Pet.4.15\"></r>. مجازيًا، <g>ὡς κ. ἐν νυκτί</g>: <r v=\"1Thess.5.2\"></r>، <r v=\"1Thess.5.4\"></r> (<g>κλέπτας</g>)، <r v=\"2Pet.3.10\"></r>، <r v=\"Rev.3.3\"></r>، <r v=\"Rev.16.15\"></r>. مجازيًا، عن المعلمين الكذبة: <r v=\"John.10.8\"></r>.†</s>","en":"<f><o>κλέπτης</o>, <g>-ου, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H1590\">גַּנָּב</h>;]</e> </et> <s><b>a thief</b>: <r v=\"Matt.6.19\"></r>, <r v=\"Matt.6.20\"></r> <r v=\"Matt.24.43\"></r>, <r v=\"Luke.12.33\"></r>, <r v=\"Luke.12.39\"></r>, <r v=\"John.10.1\"></r>, <r v=\"John.10.10\"></r> <r v=\"John.12.6\"></r>, <r v=\"1Cor.6.10\"></r>, <r v=\"1Pet.4.15\"></r>. Fig., <g>ὡς κ. ἐν νυκτί</g>, <r v=\"1Thess.5.2\"></r>, <r v=\"1Thess.5.4\"></r> (<g>κλέπτας</g>, WH, txt., R, mg.; v. Lft., <i>Notes</i>, 73; but cf. also M, <i>Th.</i>, l.c.), <r v=\"2Pet.3.10\"></r>, <r v=\"Rev.3.3\"></r> <r v=\"Rev.16.15\"></r>. Metaph., of false teachers, <r v=\"John.10.8\"></r>.†</s> <sy><i>SYN.</i>: <g>λῃστής</g>, <i>a robber</i>, <i>a brigand</i> who plunders, openly, with violence; <g>κ.</g> is a <i>thief</i> who steals in secret, by fraud and cunning (Tr., <i>Syn.</i>, § xliv).</sy>"},"G2873":{"l":"κόπος","o":23,"ar":"<f><o>κόπος</o>، <g>-ου, ὁ</g></f> <s n=\"1.\"><b>ضرب</b>، <b>لطم</b> (في <r v=\"Jer.45.3\"></r> = <g>κοπετός</g>).</s> <s n=\"2.\"><b>تعب شاق</b>، <b>عناء</b>: <r v=\"John.4.38\"></r>، <r v=\"1Cor.3.8\"></r> <r v=\"1Cor.15.58\"></r>، <r v=\"1Thess.3.5\"></r>؛ <g>κ. τ. ἀγάπης</g>، <r v=\"1Thess.1.3\"></r>؛ <g>ἔργα καὶ κ.</g>، <r v=\"Rev.2.2\"></r>؛ <g>κ. καὶ μόχθος</g>، <r v=\"2Cor.11.27\"></r>، <r v=\"1Thess.2.9\"></r>، <r v=\"2Thess.3.8\"></r>؛ جمع، <g>ἐν κ.</g>، <r v=\"2Cor.6.5\"></r> <r v=\"2Cor.10.15\"></r> <r v=\"2Cor.11.23\"></r>؛ <g>ἐκ τ. κ.</g>، <r v=\"Rev.14.13\"></r>؛ <g>κόπους</g> (<g>-ον</g>) <g>παρέχειν</g>، مع القابل للشخص، <r v=\"Matt.26.10\"></r>، <r v=\"Mark.14.6\"></r>، <r v=\"Luke.11.7\"></r> <r v=\"Luke.18.5\"></r>، <r v=\"Gal.6.17\"></r>.†</s>","en":"<f><o>κόπος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>κόπτω</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5999\">עָמָל</h>, also for <h n=\"H205\">אָוֶן</h>, etc.;]</e> </et> <s n=\"1.\"><b>a striking</b>, <b>beating</b> (in <r v=\"Jer.45.3\"></r> = <g>κοπετός</g>).</s> <s n=\"2.\"><b>laborious toil</b>, <b>trouble</b>: <r v=\"John.4.38\"></r>, <r v=\"1Cor.3.8\"></r> <r v=\"1Cor.15.58\"></r>, <r v=\"1Thess.3.5\"></r>; <g>κ. τ. ἀγάπης</g>, <r v=\"1Thess.1.3\"></r>; <g>ἔργα καὶ κ.</g>, <r v=\"Rev.2.2\"></r>; <g>κ. καὶ μόχθος</g>, <r v=\"2Cor.11.27\"></r>, <r v=\"1Thess.2.9\"></r>, <r v=\"2Thess.3.8\"></r>; pl., <g>ἐν κ.</g>, <r v=\"2Cor.6.5\"></r> <r v=\"2Cor.10.15\"></r> <r v=\"2Cor.11.23\"></r>; <g>ἐκ τ. κ.</g>, <r v=\"Rev.14.13\"></r>; <g>κόπους</g> (<g>-ον</g>) <g>παρέχειν</g> (in cl. more freq. <g>π. πράγματα, πονον</g>), c. dat. pers., <r v=\"Matt.26.10\"></r>, <r v=\"Mark.14.6\"></r>, <r v=\"Luke.11.7\"></r> <r v=\"Luke.18.5\"></r>, <r v=\"Gal.6.17\"></r>.†</s> <sy><i>SYN.</i>: <g>μόλθος</g>, <i>labour</i>; <g>πόνος</g> (q.v.), <i>toil</i>, <i>painful effort</i>; in cl., \"<g>π.</g> gives prominence to the effort (work as requiring force), <g>κ.</g> to the fatigue, <g>μ.</g> (chiefly poetic) to the hardship\" (Thayer, s.v. <g>κ.</g>).</sy>"},"G2839":{"l":"κοινός","o":14,"ar":"<f><o>κοινός</o>، <g>-ή, -όν</g>،</f> <s n=\"1.\"><b>مشترك</b> (عام؛ = اللاتينية <l>communis</l>): <r v=\"Acts.2.44\"></r> <r v=\"Acts.4.32\"></r>؛ <g>κ. πίστις</g>، <r v=\"Titus.1.4\"></r>؛ <g>σωτηρία</g>، <r v=\"Jude.1.3\"></r>.</s> <s n=\"2.\"><b>عاميّ</b> (مألوف؛ = <l>vulgaris</l>)؛ ومن ثمّ في السبعينية (<r v=\"1Macc.1.47\"></r>، وفي مواضع أخرى) والعهد الجديد: <b>غير مقدَّس</b>، <b>نجس، دنس</b> (وفي الكلاسيكية <g>βέβηλος</g>، انظره): <r v=\"Mark.7.2\"></r>، <r v=\"Mark.7.5\"></r>، <r v=\"Acts.10.14\"></r>، <r v=\"Acts.10.28\"></r> <r v=\"Acts.11.8\"></r>، <r v=\"Rom.14.14\"></r>، <r v=\"Heb.10.29\"></r>، <r v=\"Rev.21.27\"></r>.†</s>","en":"<f><o>κοινός</o>, <g>-ή, -όν</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Prov.1.14\"></r> (<h n=\"H259\">אֶחָד</h>) <r v=\"Prov.21.9\"></r> <r v=\"Prov.25.24\"></r> (<h n=\"H2267\">חֶבֶר</h>), <r v=\"Wis.7.3\"></r>, al.;]</e> </et> <s n=\"1.\"><b>common</b> (general; = Lat. <l>communis</l>): <r v=\"Acts.2.44\"></r> <r v=\"Acts.4.32\"></r>; <g>κ. πίστις</g>, <r v=\"Titus.1.4\"></r>; <g>σωτηρία</g>, <r v=\"Jude.1.3\"></r>.</s> <s n=\"2.\"><b>common</b> (ordinary; = <l>vulgaris</l>); hence in LXX (<r v=\"1Macc.1.47\"></r>, al.) and NT, <b>unhallowed</b>, <b>unclean</b> (cl., <g>βέβηλος</g>, q.v.): <r v=\"Mark.7.2\"></r>, <r v=\"Mark.7.5\"></r>, <r v=\"Acts.10.14\"></r>, <r v=\"Acts.10.28\"></r> <r v=\"Acts.11.8\"></r>, <r v=\"Rom.14.14\"></r>, <r v=\"Heb.10.29\"></r>, <r v=\"Rev.21.27\"></r>.†</s>"},"G2881":{"l":"κορίνθιος","o":2,"ar":"<f><o>κορίνθιος</o>، <g>-α, -ον</g>،</f> <s><b>كورنثي</b>؛ اسمًا، <g>ὁ Κ.</g>، <b>رجل كورنثي</b>: <r v=\"Acts.18.8\"></r>، <r v=\"Acts.18.27\"></r>، <r v=\"2Cor.6.11\"></r>؛ عنوان رسالتي كورنثوس الأولى والثانية.†</s>","en":"<f><o>κορίνθιος</o>, <g>-α, -ον</g>,</f> <s><b>Corinthian</b>; as subst., <g>ὁ Κ.</g>, <b>a Corinthian</b>: <r v=\"Acts.18.8\"></r>, <r v=\"Acts.18.27\"></r> (WH, txt., R, omit), <r v=\"2Cor.6.11\"></r>; 1Co, 2Co, <i>tit</i>.†</s>"},"G2864":{"l":"κόμη","o":1,"ar":"<f><o>κόμη</o>، <g>-ης, ἡ</g>،</f> <s><b>الشَّعر</b>: <r v=\"1Cor.11.15\"></r>.†</s>","en":"<f><o>κόμη</o>, <g>-ης, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Num.6.5\"></r>, <r v=\"Ezek.44.20\"></r> (<h n=\"H6545\">פֶּרַע</h>), al.;]</e> </et> <s><b>the hair</b>: <r v=\"1Cor.11.15\"></r>.†</s>"},"G2880":{"l":"κορέννυμι","o":2,"ar":"<f>** <o>κορέννυμι</o></f> <s><b>أشبع</b>: المبني للمجهول، <g>τροφῆς</g>، <r v=\"Acts.27.38\"></r>؛ مجازيًا عن الأمور الروحية، <r v=\"1Cor.4.8\"></r>.†</s>","en":"<f>** <o>κορέννυμι</o></f> <et> <e t=\"derivation\">(&lt; <g>κόρος</g>, <i>surfeit</i>),</e> <e t=\"septuagint\">[in Sm.: <r v=\"Ps.22.27\"></r>, Al, <r v=\"Ps.103.5\"></r>*;]</e> </et> <s><b>to satisfy</b>: pass., <g>τροφῆς</g>, <r v=\"Acts.27.38\"></r>; metaph., of spiritual things, <r v=\"1Cor.4.8\"></r>.†</s>"},"G2857":{"l":"Κολοσσαί","o":1,"ar":"<f><o>Κολοσσαί</o></f> <s><b>كولوسي</b>، مدينة على نهر ليكوس في فريجية: <r v=\"Col.1.2\"></r>.†</s>","en":"<f><o>Κολοσσαί</o></f> <et> <e t=\"derivation\">(so in cl.; <g>-ασσαί</g>, Rec., LTr.), <g>-ῶν, αἰ</g>,</e> </et> <s><b>Colossæ</b>, a city on the Lycus in Phrygia: <r v=\"Col.1.2\"></r>.†</s>"},"G2837":{"l":"κοιμάω","o":18,"ar":"<f><o>κοιμάω</o>، <g>-ῶ</g>،</f> <s><b>أنام، جعله ينام</b>. وفي الصيغة الوسطى والمبني للمجهول: <b>نام، رقد</b>: <r v=\"Matt.28.13\"></r>، <r v=\"Luke.22.45\"></r>، <r v=\"John.11.12\"></r>، <r v=\"Acts.12.6\"></r>. ومجازيًا عن الموت: <r v=\"Matt.27.52\"></r>، <r v=\"John.11.11\"></r> <r v=\"Acts.7.60\"></r> <r v=\"Acts.13.36\"></r>، <r v=\"1Cor.7.39\"></r> <r v=\"1Cor.11.30\"></r> <r v=\"1Cor.15.6\"></r>، <r v=\"1Cor.15.18\"></r>، <r v=\"1Cor.15.20\"></r>، <r v=\"1Cor.15.51\"></r>، <r v=\"1Thess.4.13-1Thess.4.15\"></r>، <r v=\"2Pet.3.4\"></r> (قارن <r v=\"Isa.14.8\"></r> <r v=\"Isa.43.17\"></r>، <r v=\"2Macc.12.45\"></r>).†</s>","en":"<f><o>κοιμάω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7901\">שׁכב</h>;]</e> </et> <s><b>to lull to sleep</b>, <b>put to sleep</b>. Mid and pass., <b>to fall asleep</b> (M, <i>Pr.</i>, 162; M, <i>Th.</i>, 1, 4, 13): <r v=\"Matt.28.13\"></r>, <r v=\"Luke.22.45\"></r>, <r v=\"John.11.12\"></r>, <r v=\"Acts.12.6\"></r>. Metaph, of death: <r v=\"Matt.27.52\"></r>, <r v=\"John.11.11\"></r> <r v=\"Acts.7.60\"></r> <r v=\"Acts.13.36\"></r>, <r v=\"1Cor.7.39\"></r> <r v=\"1Cor.11.30\"></r> <r v=\"1Cor.15.6\"></r>, <r v=\"1Cor.15.18\"></r>, <r v=\"1Cor.15.20\"></r>, <r v=\"1Cor.15.51\"></r>, <r v=\"1Thess.4.13-1Thess.4.15\"></r>, <r v=\"2Pet.3.4\"></r> (cf. <r v=\"Isa.14.8\"></r> <r v=\"Isa.43.17\"></r>, <r v=\"2Macc.12.45\"></r>).†</s> <sy><i>SYN.</i>: <g>καθεύδω</g>.</sy>"},"G2852":{"l":"κολαφίζω","o":5,"ar":"<f>*† <o>κολαφίζω</o></f> <s><b>لكم</b>، <b>لطم</b>: <r v=\"Matt.26.67\"></r>، <r v=\"Mark.14.65\"></r>، <r v=\"2Cor.12.7\"></r>؛ المبني للمجهول، <r v=\"1Cor.4.11\"></r>، <r v=\"1Pet.2.20\"></r>.†</s>","en":"<f>*† <o>κολαφίζω</o></f> <et> <e t=\"derivation\">(&lt; <g>κόλαφος</g> = Att., <g>κόνδυλοι</g>, <i>the knuckles</i>, <i>the closed fist</i>),</e> </et> <s><b>to strike with the fist</b>, <b>to buffet</b>: <r v=\"Matt.26.67\"></r>, <r v=\"Mark.14.65\"></r>, <r v=\"2Cor.12.7\"></r>; pass., <r v=\"1Cor.4.11\"></r>, <r v=\"1Pet.2.20\"></r>.†</s>"},"G2890":{"l":"Κούαρτος","o":1,"ar":"<f><o>Κούαρτος</o>، <g>-ου, ὁ</g> (اسم لاتيني)</f> <s><b>كوارتس</b>: <r v=\"Rom.16.23\"></r>.†</s>","en":"<f><o>Κούαρτος</o>, <g>-ου, ὁ</g> (Lat.)</f> <s><b>Quartus</b>: <r v=\"Rom.16.23\"></r>.†</s>"},"G2824":{"l":"κλίμα","o":3,"ar":"<f><o>κλίμα</o>، <g>-τος, τό</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>ميل</b>، <b>انحدار</b>، خاصةً الانحدار من خط الاستواء إلى القطب.</s> <s n=\"2.\"><b>إقليم، ناحية</b>: في الجمع، <r v=\"Rom.15.23\"></r>، <r v=\"2Cor.11.10\"></r>، <r v=\"Gal.1.21\"></r>.†</s>","en":"<f><o>κλίμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>κλίνω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Judg.20.2\"></r> A (<h n=\"H6438\">פִּנָּה</h>)*;]</e> </et> <s n=\"1.\"><b>an inclination</b>, <b>slope</b>, esp. the slope from the equator to the pole (Arist).</s> <s n=\"2.\"><b>a region</b> (Polyb., al.): pl., <r v=\"Rom.15.23\"></r>, <r v=\"2Cor.11.10\"></r>, <r v=\"Gal.1.21\"></r>.†</s>"},"G2850":{"l":"κολακία","o":1,"ar":"<f>* <o>κολακία</o>، <g>-ας, ἡ</g></f> <s><b>تملّق</b>: <r v=\"1Thess.2.5\"></r>.†</s>","en":"<f>* <o>κολακία</o> (Rec. <g>-εία</g>), <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>κολακεύω</g>, <i>to flatter</i>), </e> </et> <s><b>flattery</b>: <r v=\"1Thess.2.5\"></r> (v. Lft., <i>Notes</i>, 23).†</s>"},"G2807":{"l":"κλείς","o":6,"ar":"<f><o>κλείς</o>، <g>-δός</g>، حالة النصب في الأتيكية <g>κλεῖν</g>، وفي المتأخرة <g>-εῖδα</g>، الجمع <g>κλεῖδες, -ας</g>، وبالإدغام <g>-εῖς, ἡ</g>،</f> <s><b>مفتاح</b>. مجازيًا، <g>τ. βασιλείας τ. οὐρανῶν</g>، <r v=\"Matt.16.19\"></r>؛ <g>τ. γνώσεως</g>، <r v=\"Luke.11.52\"></r>؛ عن مفتاح داود (قارن السبعينية، <r v=\"Isa.22.22\"></r>)، <r v=\"Rev.3.7\"></r>؛ <g>τ. θανάτου κ. τ. ᾅδου</g>، <r v=\"Rev.1.18\"></r>؛ <g>τ. ἀβύσσου</g>، <r v=\"Rev.20.1\"></r>؛ <g>τ. φρέατος τῆς ἀ.</g>، <r v=\"Rev.9.1\"></r>.†</s>","en":"<f><o>κλείς</o>, <g>-δός</g>, Att.. acc., <g>κλεῖν</g>, later <g>-εῖδα</g>, pl., <g>κλεῖδες, -ας</g>, contr., <g>-εῖς, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H4668\">מַפְתֵּחַ</h>, <r v=\"Isa.22.22\"></r>, al.;]</e> </et> <s><b>a key</b>. Fig., <g>τ. βασιλείας τ. οὐρανῶν</g>, <r v=\"Matt.16.19\"></r>; <g>τ. γνώσεως</g>, <r v=\"Luke.11.52\"></r>; of David (cf. LXX, <r v=\"Isa.22.22\"></r>), <r v=\"Rev.3.7\"></r>; <g>τ. θανάτου κ. τ. ᾅδου</g>, <r v=\"Rev.1.18\"></r>; <g>τ. ἀβύσσου</g>, <r v=\"Rev.20.1\"></r>; <g>τ. φρέατος τῆς ἀ.</g>, <r v=\"Rev.9.1\"></r>.†</s>"},"G2854":{"l":"κολλούριον","o":1,"ar":"<f><o>κολλούριον</o></f> <s n=\"1.\"><b>رغيف خبز صغير</b> (قارن السبعينية، <r v=\"1Kgs.12.24\"></r>).</s> <s n=\"2.\">(عادةً في الجمع) <b>كُحْل، مرهم للعين</b> على شكل رغيف صغير: <r v=\"Rev.3.18\"></r>.†</s>","en":"<f><o>κολλούριον</o></f> <et> <e t=\"derivation\">(TTr., <g>κολλύ-</g>, the more usual form), <g>-ου, τό</g> (dimin. of <g>κολλύρα</g> = <g>κόλλιξ</g>, <i>a coarse bread roll</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"1Kgs.12.24\"></r><i>hil</i> B*;]</e> </et> <s n=\"1.\"><b>a small bread roll</b> (LXX, <r v=\"1Kgs.12.24\"></r><i>hil</i>).</s> <s n=\"2.\">(Usually in pl., LS, s.v.) <b>an eye salve</b> shaped like a roll: <r v=\"Rev.3.18\"></r>.†</s>"},"G2871":{"l":"κοπή","o":1,"ar":"<f><o>κοπή</o>، <g>-ῆς, ἡ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>ضربة</b>، <b>دقّ</b> (كما في الهاون).</s> <s n=\"2.\">في السبعينية: <b>ضرب</b> في المعركة، <b>كسرة</b>: <r v=\"Heb.7.1\"></r><i>(السبعينية)</i>.†</s>","en":"<f><o>κοπή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>κόπτω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Gen.14.17\"></r>, <r v=\"Josh.10.20\"></r> (<h n=\"H5221\">נכה</h> hi., <h n=\"H4347\">מַכָּה</h>), <r v=\"Deut.28.25\"></r> (<h n=\"H5062\">נגף</h>), <r v=\"Jdt.15.7\"></r>*;]</e> </et> <s n=\"1.\">in cl., <b>a stroke</b>, <b>a pounding</b> (as in a mortar).</s> <s n=\"2.\">In LXX, <b>a smiting</b> in battle: <r v=\"Heb.7.1\"></r><i>(LXX)</i>.†</s>"},"G2875":{"l":"κόπτω","o":10,"ar":"<f><o>κόπτω</o>،</f> <s n=\"1.\"><b>ضرب</b>، <b>لطم</b>.</s> <s n=\"2.\"><b>قطع</b>: مع منصوب الشيء، يليه <g>ἀπό</g>، <r v=\"Matt.21.8\"></r>؛ <g>ἐκ</g>، <r v=\"Mark.11.8\"></r>. الصيغة الوسطى: <b>لطم صدره</b> حزنًا، <b>ناح</b>، <b>بكى على</b>: <r v=\"Matt.11.17\"></r> <r v=\"Matt.24.30\"></r>؛ مع منصوب الشخص، <r v=\"Luke.8.52\"></r> <r v=\"Luke.23.27\"></r>؛ يليه <g>ἐπί</g> مع المنصوب، <r v=\"Rev.1.7\"></r> <r v=\"Rev.18.9\"></r> (قارن <g>ἀνα-</g>، <g>ἀπο-</g>، <g>ἐκ-</g>، <g>ἐν-</g>، <g>κατα-</g>، <g>προ-</g>، <g>προσ-κόπτω</g>).†</s>","en":"<f><o>κόπτω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H3772\">כּרת</h>, <h n=\"H5594\">ספד</h>, <h n=\"H5221\">נכה</h> hi., etc.;]</e> </et> <s n=\"1.\"><b>to strike</b>, <b>smite</b>.</s> <s n=\"2.\"><b>to cut off</b>: c. acc. rei, seq. <g>ἀπό</g>, <r v=\"Matt.21.8\"></r>; <g>ἐκ</g>, <r v=\"Mark.11.8\"></r>. Mid., <b>to beat one's breast</b> with grief, <b>to mourn</b>, <b>bewail</b>: <r v=\"Matt.11.17\"></r> <r v=\"Matt.24.30\"></r>; c. acc. pers., <r v=\"Luke.8.52\"></r> <r v=\"Luke.23.27\"></r>; seq. <g>ἐπί</g>, c. acc., <r v=\"Rev.1.7\"></r> <r v=\"Rev.18.9\"></r> (cf. <g>ἀνα-</g>, <g>ἀπο-</g>, <g>ἐκ-</g>, <g>ἐν-</g>, <g>κατα-</g>, <g>προ-</g>, <g>προσ-κόπτω</g>).†</s> <sy><i>SYN.</i>: <g>θρηνέω</g>, q.v.</sy>"},"G2849":{"l":"κολάζω","o":2,"ar":"<f><o>κολάζω</o></f> <s n=\"1.\"><b>قصّ</b>، <b>بتر</b>، <b>قلّم</b>.</s> <s n=\"2.\"><b>كبح</b>، <b>ضبط</b>.</s> <s n=\"3.\"><b>أدّب</b>، <b>قوّم</b>، <b>عاقب</b>: المبني للمجهول، <r v=\"2Pet.2.9\"></r>؛ الصيغة الوسطى: <b>جعله يُعاقَب</b> (<r v=\"3Macc.7.3\"></r>): <r v=\"Acts.4.21\"></r>.†</s>","en":"<f><o>κολάζω</o></f> <et> <e t=\"derivation\">(&lt; <g>κόλος</g>, <i>docked</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Dan.6.12\"></r> (<r v=\"Dan.6.13\"></r>) (no Heb.), <r v=\"1Esd.8.24\"></r>, <r v=\"Wis.3.4\"></r> (and freq.), <r v=\"1Macc.7.7\"></r>, al.;]</e> </et> <s n=\"1.\"><b>to curtail</b>, <b>dock</b>, <b>prune</b>.</s> <s n=\"2.\"><b>to check</b>, <b>restrain</b>.</s> <s n=\"3.\"><b>to chastise</b>, <b>correct</b>, <b>punish</b>: pass., <r v=\"2Pet.2.9\"></r>; mid., <b>cause to be punished</b> (<r v=\"3Macc.7.3\"></r>): <r v=\"Acts.4.21\"></r>.†</s>"},"G2827":{"l":"κλίνω","o":7,"ar":"<f><o>κλίνω</o>،</f> <s n=\"1.\"><b>أمال، حنى</b>: <g>τ. κεφαλήν</g> (عن المحتضر)، <r v=\"John.19.30\"></r>؛ <g>τ. πρόσωτον</g> (عن المرتعبين)، <r v=\"Luke.24.5\"></r>.</s> <s n=\"2.\"><b>أسند</b>، <b>أراح</b>: <g>τ. κεφαλήν</g> (في النوم)، <r v=\"Matt.8.20\"></r>، <r v=\"Luke.9.58\"></r>.</s> <s n=\"3.\">عن الجنود، <b>ردّ</b> (إلى الهزيمة)، <g>παρεμβολάς</g>، <r v=\"Heb.11.34\"></r>.</s> <s n=\"4.\">في اليونانية المتأخرة، <b>مال (نحو الزوال)</b>: لازم، <g>ἡ ἡμέρα</g>، <r v=\"Luke.9.12\"></r> <r v=\"Luke.24.29\"></r>.†</s>","en":"<f><o>κλίνω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5186\">נטה</h>;]</e> </et> <s n=\"1.\"><b>to make to bend</b>, <b>to bow</b>: <g>τ. κεφαλήν</g> (of one dying), <r v=\"John.19.30\"></r>; <g>τ. πρόσωτον</g> (of terrified persons), <r v=\"Luke.24.5\"></r>.</s> <s n=\"2.\"><b>to make to lean</b>, <b>to rest</b>: <g>τ. κεφαλήν</g> (in sleep), <r v=\"Matt.8.20\"></r>, <r v=\"Luke.9.58\"></r>.</s> <s n=\"3.\">As in Hom., of soldiers, <b>to turn</b> (to flight), <g>παρεμβολάς</g>, <r v=\"Heb.11.34\"></r>.</s> <s n=\"4.\">In late Gk. (as mid. in cl.), <b>to decline</b>: intrans., <g>ἡ ἡμέρα</g>, <r v=\"Luke.9.12\"></r> <r v=\"Luke.24.29\"></r>.†</s>"},"G2809":{"l":"κλέμμα","o":1,"ar":"<f><o>κλέμμα</o>، <g>-τος, τό</g></f> <s n=\"1.\"><b>شيء مسروق</b>.</s> <s n=\"2.\">= <g>κλοπή</g>، <b>سرقة</b>: في الجمع، <r v=\"Rev.9.21\"></r>.†</s>","en":"<f><o>κλέμμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>κλέπτω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Gen.31.39\"></r>, <r v=\"Exod.22.3\"></r>, <r v=\"Exod.22.4\"></r> (<r v=\"Exod.22.2\"></r>, <r v=\"Exod.22.3\"></r>) (<h n=\"H1589\">גָּנַב</h>, <h n=\"H1591\">גְּנֵבָה</h>)*;]</e> </et> <s n=\"1.\"><b>a thing stolen</b> (Arist., LXX).</s> <s n=\"2.\">= <g>κλοπή</g>, <b>theft</b> (Plato, al.): pl., <r v=\"Rev.9.21\"></r>.†</s>"},"G2851":{"l":"κόλασις","o":2,"ar":"<f><o>κόλασις</o>، <g>-εως, ἡ</g>،</f> <s><b>تأديب</b>، <b>جزاء</b>، <b>عذاب (عقاب)</b>: <r v=\"Matt.25.46\"></r>، <r v=\"1John.4.18\"></r>.†</s>","en":"<f><o>κόλασις</o>, <g>-εως, ἡ</g>,</f> <et> <e t=\"derivation\">(&lt; <g>κολάζω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Ezek.14.3-Ezek.14.7\"></r> <r v=\"Ezek.18.30\"></r> <r v=\"Ezek.44.12\"></r>, (<h n=\"H4383\">מִכְשׁוֹל</h>) <r v=\"Ezek.43.11\"></r>, <g>λαμβάνειν τὴν κ.</g> (<h n=\"H3637\">כּלם</h> ni.); <r v=\"Wis.11.13\"></r> <r v=\"Wis.16.2\"></r>, <r v=\"Wis.16.24\"></r> <r v=\"Wis.19.4\"></r>, <r v=\"Jer.18.20\"></r>, II-IV Mac<i>5</i>*;]</e> </et> <s><b>correction</b>, <b>penalty</b>, <b>punishment</b>: <r v=\"Matt.25.46\"></r>, <r v=\"1John.4.18\"></r>.†</s> <sy><i>SYN.</i>: <g>τιμωρία</g>, <i>requital</i>. Arist. distinguishes between <g>κ.</g> as that which, being disciplinary, has reference to the sufferer, and <g>τ.</g> as that which, being penal, has reference to the satisfaction of him who inflicts (v. Thayer, s.v. <g>κ.</g>, and cf. Tr., <i>Syn.</i>, § vii). But in late Gk. especially, the distinction is not always maintained (v. reff. in Thayer).</sy>"},"G2808":{"l":"κλείω","o":16,"ar":"<f><o>κλείω</o>،</f> <s><b>أغلق</b>: <g>θύραν</g>، <r v=\"Matt.6.6\"></r>؛ <g>τ. ἄβυσσον</g>، <r v=\"Rev.20.3\"></r>؛ المبني للمجهول، <g>θύρα</g>، <r v=\"Matt.25.10\"></r>، <r v=\"Luke.11.7\"></r> (جمع)، <r v=\"John.20.19\"></r>، <r v=\"John.20.26\"></r>، <r v=\"Acts.21.30\"></r>؛ <g>δεσμωτήριον</g>، <r v=\"Acts.5.23\"></r>؛ <g>πυλῶνες</g>، <r v=\"Rev.21.25\"></r>. مجازيًا، <g>τ. οὐρανόν</g>، <r v=\"Luke.4.25\"></r>، <r v=\"Rom.11.6\"></r>؛ <g>τ. σπλάγχνα</g>، <r v=\"1John.3.17\"></r>؛ <g>τ. βασιλείαν</g>، <r v=\"Matt.23.14\"></r>؛ ونفسه مطلقًا، <r v=\"Rev.3.7\"></r>؛ <g>τ. θύραν</g>، <r v=\"Rev.3.8\"></r>. (قارن <g>ἀπο-</g>، <g>ἐκ-</g>، <g>κατα-</g>، <g>συν-κλείω</g>.)†</s>","en":"<f><o>κλείω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5462\">סגר</h>;]</e> </et> <s><b>to shut</b>: <g>θύραν</g>, <r v=\"Matt.6.6\"></r>; <g>τ. ἄβυσσον</g>, <r v=\"Rev.20.3\"></r>; pass., <g>θύρα</g>, <r v=\"Matt.25.10\"></r>, <r v=\"Luke.11.7\"></r> (pl.), <r v=\"John.20.19\"></r>, <r v=\"John.20.26\"></r>, <r v=\"Acts.21.30\"></r>; <g>δεσμωτήριον</g>, <r v=\"Acts.5.23\"></r>; <g>πυλῶνες</g>, <r v=\"Rev.21.25\"></r>. Metaph., <g>τ. οὐρανόν</g>, <r v=\"Luke.4.25\"></r>, <r v=\"Rom.11.6\"></r>; <g>τ. σπλάγχνα</g>, <r v=\"1John.3.17\"></r>; <g>τ. βασιλείαν</g>, <r v=\"Matt.23.14\"></r>; id. absol., <r v=\"Rev.3.7\"></r>; <g>τ. θύραν</g>, <r v=\"Rev.3.8\"></r>. (Cf. <g>ἀπο-</g>, <g>ἐκ-</g>, <g>κατα-</g>, <g>συν-κλείω</g>.)†</s>"},"G2847":{"l":"κόκκινος","o":6,"ar":"<f>† <o>κόκκινος</o>، <g>-η, -ον</g></f> <s><b>قرمزي</b>: <r v=\"Matt.27.28\"></r>، <r v=\"Heb.9.19\"></r>، <r v=\"Rev.17.3\"></r>؛ المحايد بلا اسم موصوف، عن الثياب، <r v=\"Rev.17.4\"></r>، <r v=\"Rev.18.12\"></r>، <r v=\"Rev.18.16\"></r>.†</s>","en":"<f>† <o>κόκκινος</o>, <g>-η, -ον</g></f> <et> <e t=\"derivation\">(&lt; <g>κόκκος</g>, as used of the \"berry\" of the <i>ilex coccifera</i>, v. <i>DB</i>, iv, 416),</e> <e t=\"septuagint\">[in LXX for <h n=\"H8438\">תּוֹלֵעָה</h>, <h n=\"H8439\">תּוֹלָע</h>, <h n=\"H8144\">שָׁנִי</h>, <r v=\"Exod.25.4\"></r>, <r v=\"Gen.38.28\"></r>, <r v=\"Isa.1.18\"></r>, al.;]</e> </et> <s><b>scarlet</b>: <r v=\"Matt.27.28\"></r>, <r v=\"Heb.9.19\"></r>, <r v=\"Rev.17.3\"></r>; neut., without substantive, of clothing, <r v=\"Rev.17.4\"></r> <r v=\"Rev.18.12\"></r>, <r v=\"Rev.18.16\"></r>,†</s>"},"G2830":{"l":"κλύδων","o":2,"ar":"<f><o>κλύδων</o>، <g>-ωνος, ὁ</g></f> <s><b>موج</b>، <b>لُجّة</b>: <r v=\"Luke.8.24\"></r>، <r v=\"Jas.1.6\"></r>.†</s>","en":"<f><o>κλύδων</o>, <g>-ωνος, ὁ</g></f> <et> <e t=\"derivation\">(<g>κλύζω</g>, of the sea, <i>to wash over</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Jon.1.4\"></r>, <r v=\"Jon.1.12\"></r> (<h n=\"H5591\">סער</h>), al.;]</e> </et> <s><b>a billow</b>, <b>surge</b>: <r v=\"Luke.8.24\"></r>, <r v=\"Jas.1.6\"></r>.†</s> <sy><i>SYN.</i>: <g>κῦμα</g>, <i>a wave</i>.</sy>"},"G2811":{"l":"κλέος","o":1,"ar":"<f><o>κλέος</o>، <g>-ους, τό</g>،</f> <s n=\"1.\"><b>إشاعة</b>، <b>خبر</b>.</s> <s n=\"2.\"><b>صيت حسن</b>، <b>شهرة</b>، <b>مجد</b>: <r v=\"1Pet.2.20\"></r>.†</s>","en":"<f><o>κλέος</o>, <g>-ους, τό</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Job.28.22\"></r> (<h n=\"H8088\">שֵׁמַע</h>) <r v=\"Job.30.8\"></r>*;]</e> </et> <s n=\"1.\"><b>a rumour</b>, <b>report</b>.</s> <s n=\"2.\"><b>good report</b>, <b>fame</b>, <b>glory</b>: <r v=\"1Pet.2.20\"></r>.†</s>"},"G2840":{"l":"κοινόω","o":14,"ar":"<f><o>κοινόω</o>، <g>-ῶ</g>،</f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>يجعله مشاعًا (عامًّا)</b>.</s> <s n=\"2.\">في السبعينية، <r v=\"4Macc.7.6\"></r>، وفي العهد الجديد (كما في <g>κοινός</g>، 2): <b>يُنجِّس طقسيًّا</b>، <b>يدنِّس</b> (= <g>βεληλόω</g> في الكلاسيكية): <r v=\"Matt.15.11\"></r>، <r v=\"Matt.15.18\"></r>، <r v=\"Matt.15.20\"></r>، <r v=\"Mark.7.15\"></r>، <r v=\"Mark.7.18\"></r>، <r v=\"Mark.7.20\"></r>، <r v=\"Mark.7.23\"></r>، <r v=\"Acts.21.28\"></r>؛ المبني للمجهول، <r v=\"Heb.9.13\"></r>.</s> <s n=\"3.\"><b>يحسبه نجسًا (دنسًا)</b> (قارن <g>δικαιόω</g>): <r v=\"Acts.10.15\"></r> <r v=\"Acts.11.9\"></r>.†</s>","en":"<f><o>κοινόω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"4Macc.7.6\"></r> <h>א</h>R*;]</e> </et> <s n=\"1.\">in cl., <b>to make common</b>.</s> <s n=\"2.\">In LXX, <r v=\"4Macc.7.6\"></r>, and NT (as <g>κοινός</g>, 2), <b>to make ceremonially unclean</b>, <b>to profane</b> (= cl., <g>βεληλόω</g>): <r v=\"Matt.15.11\"></r>, <r v=\"Matt.15.18\"></r>, <r v=\"Matt.15.20\"></r>, <r v=\"Mark.7.15\"></r>, <r v=\"Mark.7.18\"></r>, <r v=\"Mark.7.20\"></r>, <r v=\"Mark.7.23\"></r>, <r v=\"Acts.21.28\"></r>; pass., <r v=\"Heb.9.13\"></r>.</s> <s n=\"3.\"><b>to count unclean</b> (cf. <g>δικαιόω</g>): <r v=\"Acts.10.15\"></r> <r v=\"Acts.11.9\"></r>.†</s> <sy><i>SYN.</i>: <g>βεβηλόω</g>. Thayer (s.v. <g>κ.</g>) mentions that Winer notes the accuracy whereby the Jews are said to use <g>κ.</g> in addressing Jews, <r v=\"Acts.21.28\"></r>, and <g>β.</g> when speaking to Felix, <r v=\"Acts.24.6\"></r> (Cremer, 362).</sy>"},"G2825":{"l":"κλίνη","o":9,"ar":"<f><o>κλίνη</o>، <g>-ης, ἡ</g></f> <s><b>سرير</b>، <b>فراش، متّكأ</b>: <r v=\"Matt.9.2\"></r>، <r v=\"Matt.9.6\"></r>، <r v=\"Mark.4.21\"></r> <r v=\"Mark.7.4\"></r>، <r v=\"Mark.7.30\"></r>، <r v=\"Luke.5.18\"></r> <r v=\"Luke.8.16\"></r> <r v=\"Luke.17.34\"></r>، <r v=\"Rev.2.22\"></r>.†</s>","en":"<f><o>κλίνη</o>, <g>-ης, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>κλίνω</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4296\">מִטָּה</h>;]</e> </et> <s><b>a bed</b>, <b>couch</b>: <r v=\"Matt.9.2\"></r>, <r v=\"Matt.9.6\"></r>, <r v=\"Mark.4.21\"></r> <r v=\"Mark.7.4\"></r>, <r v=\"Mark.7.30\"></r>, <r v=\"Luke.5.18\"></r> <r v=\"Luke.8.16\"></r> <r v=\"Luke.17.34\"></r>, <r v=\"Rev.2.22\"></r> (cf. MM, <i>Exp.</i>, xv).†</s>"},"G2879":{"l":"Κορέ","o":1,"ar":"<f><o>Κορέ</o> لا يُصرَّف.</f> <s><b>قورح</b>: <r v=\"Jude.1.11\"></r>.†</s>","en":"<f><o>Κορέ</o> indecl.</f> <et> <e t=\"derivation\">(in FlJ, <g>-έου</g>), <g>ὁ</g></e> <e t=\"derivation\">(Heb. <h n=\"H7140\">קֶרַח</h>),</e> </et> <s><b>Korah</b>: <r v=\"Jude.1.11\"></r>.†</s>"},"G2868":{"l":"κονιορτός","o":5,"ar":"<f><o>κονιορτός</o>، <g>-οῦ, ὁ</g></f> <s>(في الكلاسيكية: <b>غبار مُثار</b>؛ <r v=\"Exod.9.9\"></r>، <r v=\"Isa.5.24\"></r>)؛ وفي العهد الجديد مجرد <b>غبار</b>: <r v=\"Matt.10.14\"></r>، <r v=\"Luke.9.5\"></r>، <r v=\"Luke.10.11\"></r>، <r v=\"Acts.13.51\"></r>، <r v=\"Acts.22.23\"></r>.†</s>","en":"<f><o>κονιορτός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>κόνις</g> or <g>κονία</g>, <i>dust</i>, <g>ὄρνυμι</g>, <i>to stir up</i>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H80\">אָבָק</h>, etc.;]</e> </et> <s>in cl., <b>dust stirred up</b> (<r v=\"Exod.9.9\"></r>, <r v=\"Isa.5.24\"></r>); in NT, simply <b>dust</b>: <r v=\"Matt.10.14\"></r>, <r v=\"Luke.9.5\"></r> <r v=\"Luke.10.11\"></r>, <r v=\"Acts.13.51\"></r> <r v=\"Acts.22.23\"></r>.†</s>"},"G2870":{"l":"κοπετός","o":1,"ar":"<f><o>κοπετός</o>، <g>-οῦ, ὁ</g></f> <s>= <g>κομμός</g> في الكلاسيكية، <b>لطم الرأس والصدر</b>، <b>نَوح</b>: يليه <g>ἐπί</g> مع قابل الشخص، <r v=\"Acts.8.2\"></r>.†</s>","en":"<f><o>κοπετός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>κόπτω</g>, mid.),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4553\">מִסְפֵּד</h>;]</e> </et> <s>= cl. <g>κομμός</g>, <b>a beating of the head and breast</b>, <b>lamentation</b>: seq. <g>ἐπί</g> c. dat. pers., <r v=\"Acts.8.2\"></r>.†</s>"},"G2883":{"l":"Κορνήλιος","o":8,"ar":"<f><o>Κορνήλιος</o>، <g>-ου, ὁ</g> (لاتيني)،</f> <s><b>كرنيليوس</b>: <r v=\"Acts.10.1\"></r> وما يليه.†</s>","en":"<f><o>Κορνήλιος</o>, <g>-ου, ὁ</g> (Lat.),</f> <s><b>Cornelius</b>: <r v=\"Acts.10.1\"></r> ff.†</s>"},"G2828":{"l":"κλισία","o":1,"ar":"<f>** <o>κλισία</o>، <g>-ας, ἡ</g></f> <s n=\"1.\"><b>موضع للاتكاء</b>؛ ومن ثم <s n=\"(a)\"><b>كوخ</b>؛</s> <s n=\"(b)\"><b>كرسي مريح</b>؛</s> <s n=\"(c)\"><b>متّكأ</b>.</s> </s> <s n=\"2.\"><b>جماعة متّكئة</b>: في الجمع، <r v=\"Luke.9.14\"></r>.†</s>","en":"<f>** <o>κλισία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>κλίνω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"3Macc.6.31\"></r> A*;]</e> </et> <s n=\"1.\"><b>a place for reclining</b>; hence, <s n=\"(a)\"><b>a hut</b>;</s> <s n=\"(b)\"><b>an easy chair</b>;</s> <s n=\"(c)\"><b>a couch</b>.</s> </s> <s n=\"2.\"><b>a company reclining</b>: pl., <r v=\"Luke.9.14\"></r> (cf. FlJ, <i>Ant.</i>, xii, 2, 12).†</s>"},"G2899":{"l":"κράσπεδον","o":5,"ar":"<f><o>κράσπεδον</o>، <g>-ου, τό</g>،</f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>حافة</b>، <b>طرف</b>.</s> <s n=\"2.\">في السبعينية والعهد الجديد: <b>هُدب</b> أو <b>طرف</b> الثوب: <r v=\"Matt.9.20\"></r> <r v=\"Matt.14.36\"></r> <r v=\"Matt.23.5\"></r>، <r v=\"Mark.6.56\"></r>، <r v=\"Luke.8.44\"></r>.†</s>","en":"<f><o>κράσπεδον</o>, <g>-ου, τό</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Num.15.38\"></r>, <r v=\"Num.15.39\"></r> (<h n=\"H6734\">צִיצִת</h>) <r v=\"Deut.22.12\"></r>, <r v=\"Zech.8.23\"></r> (<h n=\"H3671\">כָּנָף</h>)*;]</e> </et> <s n=\"1.\">in cl., <b>an edge</b>, <b>border</b>.</s> <s n=\"2.\">In LXX (v. supr.) and NT,<b> a tassel</b> or <b>corner</b>: <r v=\"Matt.9.20\"></r> <r v=\"Matt.14.36\"></r> <r v=\"Matt.23.5\"></r>, <r v=\"Mark.6.56\"></r>, <r v=\"Luke.8.44\"></r>.†</s>"},"G2866":{"l":"κομψός","o":1,"ar":"<f>* <o>κομψός</o>، <g>-ή, -όν</g></f> <s><b>حسن الهندام</b>، <b>أنيق</b>، <b>حسن</b>؛ المحايد من صيغة التفضيل، <g>κομψότερον ἔχειν</g> (قارن <g>κόμψως</g> <g>ἔχειν</g>، بمعنى «صار في حالٍ أحسن»): <r v=\"John.4.52\"></r>.†</s>","en":"<f>* <o>κομψός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>κομέω</g>, <i>to take care of</i>),</e> </et> <s><b>well-dressed</b>, <b>elegant</b>, <b>fine</b>; compar. neut., <g>κομψότερον ἔχειν</g> (cf. <g>κόμψως</g> <g>ἔχειν</g>, Epict., and colloq. Eng., \"<i>to be doing finely</i>\"): <r v=\"John.4.52\"></r>.†</s>"},"G2804":{"l":"Κλαύδιος","o":3,"ar":"<f><o>Κλαύδιος</o>، <g>-ου, ὁ</g>،</f> <s><b>كلوديوس</b>؛ <s n=\"1.\">الإمبراطور: <r v=\"Acts.11.28\"></r> <r v=\"Acts.18.2\"></r>.</s> <s n=\"2.\">أمير ألف (قائد عسكري): <b>كلوديوس ليسياس</b>: <r v=\"Acts.23.26\"></r>.†</s> </s>","en":"<f><o>Κλαύδιος</o>, <g>-ου, ὁ</g>,</f> <s><b>Claudius</b>; <s n=\"1.\">the Emperor: <r v=\"Acts.11.28\"></r> <r v=\"Acts.18.2\"></r>.</s> <s n=\"2.\">A military tribune, <b>C. Lysias</b>: <r v=\"Acts.23.26\"></r>.†</s> </s>"},"G2835":{"l":"κοδράντης","o":2,"ar":"<f>*† <o>κοδράντης</o>، <g>-ου, ὁ</g> (اللاتينية <l>quadrans</l>: ربع <i>الأَس</i>)،</f> <s><b>ربع (كوادرانس)</b> (الترجمة المعتمدة: <i>فلس</i>): <r v=\"Matt.5.26\"></r>، <r v=\"Mark.12.42\"></r>.†</s>","en":"<f>*† <o>κοδράντης</o>, <g>-ου, ὁ</g> (Lat. <l>quadrans</l>, the fourth part of an <i>as</i>),</f> <s><b>a quadrans</b> (AV, <i>farthing</i>): <r v=\"Matt.5.26\"></r>, <r v=\"Mark.12.42\"></r>.†</s>"},"G2814":{"l":"κλῆμα","o":7,"ar":"<f><o>κλῆμα</o>، <g>-τος, τό</g></f> <s><b>غصن الكرمة</b>، <b>قضيب الكرمة</b>: <r v=\"John.15.2\"></r>، <r v=\"John.15.4-John.15.6\"></r>.†</s>","en":"<f><o>κλῆμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>κλάω</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2156\">זְמוֹרָה</h>, <h n=\"H1808\">דָּלִית</h>, <r v=\"Ezek.15.2\"></r> <r v=\"Ezek.17.6\"></r>, <r v=\"Ezek.17.7\"></r>, al.;]</e> </et> <s><b>a vine-twig</b>, <b>vine-branch</b>: <r v=\"John.15.2\"></r>, <r v=\"John.15.4-John.15.6\"></r>.†</s>"},"G2897":{"l":"κραιπάλη","o":1,"ar":"<f>* <o>κραιπάλη</o></f> <s><b>غثيان السُّكر</b> (الترجمات الإنجليزية: <i>خُمار</i>): <r v=\"Luke.21.34\"></r>.†</s>","en":"<f>* <o>κραιπάλη</o></f> <et> <e t=\"derivation\">(<g>κρεπάλη</g>, WH), <g>-ης, ἡ</g> (cf. <g>κραιπαλάω</g> for <h n=\"H7910\">שׁכר</h>, <r v=\"Isa.24.20\"></r> <r v=\"Isa.29.9\"></r>),</e> </et> <s><b>drunken nausea</b> (EV, <i>surfeiting</i>): <r v=\"Luke.21.34\"></r>.†</s> <sy><i>SYN.</i>: <g>κῶμος</g>, <i>revelling</i>; <g>μέθη</g>, <i>drunkeness</i>; <g>οἰνοφλυγία</g>, <i>a debauch</i>; <g>πότος</g>, <i>a drinking bout</i> (v. Tr., <i>Syn.</i>, § lxi).</sy>"},"G2832":{"l":"Κλωπᾶς","o":1,"ar":"<f><o>Κλωπᾶς</o>، <g>-ᾶ, ὁ</g> (آرامي)،</f> <s><b>كلوبا</b>: <r v=\"John.19.25\"></r>.†</s>","en":"<f><o>Κλωπᾶς</o>, <g>-ᾶ, ὁ</g> (Aram.; on the original, v. Lft., <i>Gal.</i>, 267 f.),</f> <s><b>Clopas</b>: <r v=\"John.19.25\"></r>.†</s>"},"G2856":{"l":"κολοβόω","o":4,"ar":"<f><o>κολοβόω</o>، <g>-ῶ</g></f> <s><b>بتر</b>، <b>قطع</b> (عضوًا)، ومن ثمّ <b>قصّر</b>، <b>اختصر</b>: <r v=\"Matt.24.22\"></r>، <r v=\"Mark.13.20\"></r>.†</s>","en":"<f><o>κολοβόω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>κολοβός</g>, <i>docked</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"2Sam.4.12\"></r> (<h n=\"H7112\">קצץ</h> pi.)*;]</e> </et> <s><b>to cut off</b>, <b>amputate</b> (LXX), hence, <b>to curtail</b>, <b>shorten</b>: <r v=\"Matt.24.22\"></r>, <r v=\"Mark.13.20\"></r>.†</s>"},"G2802":{"l":"Καῦδα","o":null,"ar":"<f><o>Καῦδα</o>، <g>ἡ</g>،</f> <s><b>كودا</b>، <b>كلودي</b>، جزيرة قرب كريت: <r v=\"Acts.27.16\"></r>.†</s>","en":"<f><o>Καῦδα</o> (TR, mg., <g>Κλαῦδα</g>; Rec. <g>Κλαύδη</g>), <g>ἡ</g>,</f> <s><b>Cauda</b>, <b>Clauda</b>, an island near Crete: <r v=\"Acts.27.16\"></r>.†</s>"},"G2846":{"l":"κοιτών","o":1,"ar":"<f><o>κοιτών</o>، <g>-ῶνος, ὁ</g></f> <s><b>مخدع، حجرة نوم</b>؛ <g>ὁ ἐπὶ τοῦ κ.</g>: <b>ناظر المضجع، الحاجب</b>: <r v=\"Acts.12.20\"></r>.†</s>","en":"<f><o>κοιτών</o>, <g>-ῶνος, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>κοίτη</g> = Att.., <g>δωμότιον</g>, v. Kennedy, <i>Sources</i>, 40),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2315\">חֶדֶר</h>, <r v=\"2Sam.4.7\"></r>, <r v=\"Joel.2.16\"></r>, <r v=\"1Esd.3.3\"></r>, al.;]</e> </et> <s><b>a bed-chamber</b>; <g>ὁ ἐπὶ τοῦ κ.</g>, <b>a chamberlain</b>: <r v=\"Acts.12.20\"></r>.†</s>"},"G2895":{"l":"κράβαττος","o":null,"ar":"<f>**† <o>κράβαττος</o>، <g>ου, ὁ</g></f> <s><b>سرير</b> (سرير معسكر)، <b>فراش</b>: <r v=\"Mark.2.4\"></r>، <r v=\"Mark.2.9\"></r>، <r v=\"Mark.2.11\"></r>، <r v=\"Mark.2.12\"></r>، <r v=\"Mark.6.55\"></r>، <r v=\"John.5.8-John.5.11\"></r>، <r v=\"Acts.5.15\"></r>، <r v=\"Acts.9.33\"></r> (قارن <r v=\"Mark.2.4\"></r>، و<g>κλίνη</g>).†</s>","en":"<f>**† <o>κράβαττος</o> (Rec. <g>κράββατος</g>), <g>ου, ὁ</g></f> <et> <e t=\"derivation\">(a Macedonian word, = Lat. <l>grabatus</l>, cl. <g>σκίμπους</g>),</e> <e t=\"septuagint\">[in Aq.: <r v=\"Amos.3.12\"></r>*;]</e> </et> <s><b>a camp bed</b>, <b>pallet</b>: <r v=\"Mark.2.4\"></r>, <r v=\"Mark.2.9\"></r>, <r v=\"Mark.2.11\"></r>, <r v=\"Mark.2.12\"></r> <r v=\"Mark.6.55\"></r>, <r v=\"John.5.8-John.5.11\"></r>, <r v=\"Acts.5.15\"></r> <r v=\"Acts.9.33\"></r> (v. Swete, <r v=\"Mark.2.4\"></r>, and cf. <g>κλίνη</g>).†</s>"},"G2801":{"l":"κλάσμα","o":9,"ar":"<f><o>κλάσμα</o>، <g>-τος, τό</g></f> <s><b>كِسرة</b>، <b>قطعة مكسورة</b>: <r v=\"Matt.14.20\"></r>، <r v=\"Matt.15.37\"></r>، <r v=\"Mark.6.43\"></r>، <r v=\"Mark.8.8\"></r>، <r v=\"Mark.8.19\"></r>، <r v=\"Mark.8.20\"></r>، <r v=\"Luke.9.17\"></r>، <r v=\"John.6.12\"></r>، <r v=\"John.6.13\"></r>.†</s>","en":"<f><o>κλάσμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>κλάω</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H6595\">פַּת</h>, <h n=\"H6400\">פֶּלַח</h>;]</e> </et> <s><b>a broken piece</b>, <b>fragment</b>: <r v=\"Matt.14.20\"></r> <r v=\"Matt.15.37\"></r>, <r v=\"Mark.6.43\"></r> <r v=\"Mark.8.8\"></r>, <r v=\"Mark.8.19\"></r>, <r v=\"Mark.8.20\"></r>, <r v=\"Luke.9.17\"></r>, <r v=\"John.6.12\"></r>, <r v=\"John.6.13\"></r>.†</s>"},"G2826":{"l":"κλινίδιον","o":2,"ar":"<f>* <o>κλινίδιον</o>، <g>-ου, τό</g>،</f> <e t=\"derivation\">تصغير <g>κλίνη</g>،</e> <s><b>فراش صغير، سرير</b>: <r v=\"Luke.5.19\"></r>، <r v=\"Luke.5.24\"></r> (قارن <g>κλινάριον</g>).†</s>","en":"<f>* <o>κλινίδιον</o>, <g>-ου, τό</g>,</f> <e t=\"derivation\">dimin. of <g>κλίνη</g>,</e> <s><b>a couch</b>: <r v=\"Luke.5.19\"></r>, <r v=\"Luke.5.24\"></r> (cf. <g>κλινάριον</g>).†</s>"},"G2876":{"l":"κόραξ","o":1,"ar":"<f><o>κόραξ</o>، <g>-ακος, ὁ</g>،</f> <s><b>غراب</b>: <r v=\"Luke.12.24\"></r>.†</s>","en":"<f><o>κόραξ</o>, <g>-ακος, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6158\">עֹרֵב</h>;]</e> </et> <s><b>a raven</b>: <r v=\"Luke.12.24\"></r>.†</s>"},"G2805":{"l":"κλαυθμός","o":9,"ar":"<f><o>κλαυθμός</o>، <g>-οῦ, ὁ</g></f> <s><b>بكاء</b>، <b>نحيب</b>، <r v=\"Acts.20.37\"></r>؛ <g>κ. καὶ ὀδυρμός</g>، <r v=\"Matt.2.18\"></r><i>(السبعينية)</i>؛ <g>ὁ κ. καὶ ὁ βρυγμός</g>، <r v=\"Matt.8.12\"></r> <r v=\"Matt.13.42\"></r>، <r v=\"Matt.13.50\"></r> <r v=\"Matt.22.13\"></r> <r v=\"Matt.24.51\"></r> <r v=\"Matt.25.30\"></r>، <r v=\"Luke.13.28\"></r>.†</s>","en":"<f><o>κλαυθμός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>κλαίω</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1065\">בְּכִי</h>;]</e> </et> <s><b>crying</b>, <b>weeping</b>, <r v=\"Acts.20.37\"></r>; <g>κ. καὶ ὀδυρμός</g>, <r v=\"Matt.2.18\"></r><i>(LXX)</i>; <g>ὁ κ. καὶ ὁ βρυγμός</g>, <r v=\"Matt.8.12\"></r> <r v=\"Matt.13.42\"></r>, <r v=\"Matt.13.50\"></r> <r v=\"Matt.22.13\"></r> <r v=\"Matt.24.51\"></r> <r v=\"Matt.25.30\"></r>, <r v=\"Luke.13.28\"></r>.†</s>"},"G2834":{"l":"Κνίδος","o":1,"ar":"<f><o>Κνίδος</o>، <g>-ου, ἡ</g>،</f> <s><b>كنيدس</b>، مدينة (وشبه جزيرة) على الساحل الجنوبي الغربي لآسيا الصغرى: <r v=\"Acts.27.7\"></r>.†</s>","en":"<f><o>Κνίδος</o>, <g>-ου, ἡ</g>,</f> <s><b>Cnidus</b>, a city (and peninsula) on S.W. coast of Asia Minor: <r v=\"Acts.27.7\"></r>.†</s>"},"G2877":{"l":"κοράσιον","o":8,"ar":"<f><o>κοράσιον</o>، <g>-ου, τό</g>،</f> <s>كلمة دارجة باقية في اليونانية الحديثة، <b>صبيّة</b>، <b>فتاة</b>: <r v=\"Matt.9.24\"></r>، <r v=\"Matt.9.25\"></r> <r v=\"Matt.14.11\"></r>، <r v=\"Mark.5.41\"></r>، <r v=\"Mark.5.42\"></r> <r v=\"Mark.6.22\"></r>، <r v=\"Mark.6.28\"></r>.†</s>","en":"<f><o>κοράσιον</o>, <g>-ου, τό</g>,</f> <et> <e t=\"derivation\">(dimin. of <g>κόρη</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5291\">נַעֲרָה</h>, <r v=\"Ruth.2.8\"></r>, al.; in <r v=\"Joel.3.3\"></r>, <r v=\"Zech.8.5\"></r> for <h n=\"H3207\">יַלְדָּה</h>;]</e> </et> <s>a colloquial word which survives in MGr. (Kennedy, <i>Sourcs</i>, 154), <b>girl</b>, <b>maiden</b>: <r v=\"Matt.9.24\"></r>, <r v=\"Matt.9.25\"></r> <r v=\"Matt.14.11\"></r>, <r v=\"Mark.5.41\"></r>, <r v=\"Mark.5.42\"></r> <r v=\"Mark.6.22\"></r>, <r v=\"Mark.6.28\"></r>.†</s>"},"G2894":{"l":"κόφινος","o":6,"ar":"<f><o>κόφινος</o>، <g>-ου, ὁ</g>،</f> <s><b>قُفّة</b>، على الأرجح من الخوص، من النوع الذي كان اليهود يحملون فيه طعامهم: <r v=\"Matt.14.20\"></r> <r v=\"Matt.16.9\"></r>، <r v=\"Mark.6.43\"></r> <r v=\"Mark.8.19\"></r> <r v=\"Luke.9.17\"></r> <r v=\"Luke.13.8\"></r>، <r v=\"John.6.13\"></r> (قارن <g>σφυρίς</g>).†</s>","en":"<f><o>κόφινος</o>, <g>-ου, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Judg.6.19\"></r> (<h n=\"H5536\">סַל</h>), <r v=\"Ps.81.6\"></r> (<h n=\"H1731\">דּוּד</h>)*;]</e> </et> <s><b>a basket</b>, probably of wicker-work, such as were carried by Jews for food: <r v=\"Matt.14.20\"></r> <r v=\"Matt.16.9\"></r>, <r v=\"Mark.6.43\"></r> <r v=\"Mark.8.19\"></r> <r v=\"Luke.9.17\"></r> <r v=\"Luke.13.8\"></r>, <r v=\"John.6.13\"></r> (cf. <g>σφυρίς</g>).†</s>"},"G2891":{"l":"κούμ","o":1,"ar":"<f><o>κούμ</o> (بالعبرية، أمر مذكر، مستعمل كأداة تعجّب، <h n=\"H6966\">קוּם</h>)،</f> <s><b>قُوم</b> (<b>قُمْ، انهض</b>): <r v=\"Mark.5.41\"></r>.†</s>","en":"<f><o>κούμ</o> (Tr., txt., <g>κοῦμ</g>, Rec. <g>κοῦμι</g>) (Heb. imperat. masc., used as an interjection, <h n=\"H6966\">קוּם</h>),</f> <s><b>koum</b> (<b>arise</b>): <r v=\"Mark.5.41\"></r>.†</s>"},"G2878":{"l":"κορβάν","o":1,"ar":"<f>*† <o>κορβάν</o>، لا يُصرَّف (بالعبرية <h n=\"H7133\">קׇרְבָּן</h>)،</f> <s><b>قربان</b>، <b>عطية</b> مقدَّمة لله: <r v=\"Mark.7.11\"></r> (قارن <g>κορβανᾶς</g>).†</s>","en":"<f>*† <o>κορβάν</o> (Rec., T, <g>-βᾶν</g>), indecl. (Heb. <h n=\"H7133\">קׇרְבָּן</h>),</f> <s><b>an offering</b>, <b>a gift</b> offered to God: <r v=\"Mark.7.11\"></r> (cf. <g>κορβανᾶς</g>).†</s>"},"G2855":{"l":"κολλυβιστής","o":3,"ar":"<f>*† <o>κολλυβιστής</o>، <g>-οῦ, ὁ</g></f> <s><b>صرّاف</b>: <r v=\"Matt.21.12\"></r>، <r v=\"Mark.11.15\"></r>، <r v=\"John.2.15\"></r> (قارن <g>κερματιοτής</g>).†</s>","en":"<f>*† <o>κολλυβιστής</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>κόλλυβος</g>, <i>a small coin</i>, <i>a rate of exchange</i>),</e> </et> <s><b>a money-changer</b>: <r v=\"Matt.21.12\"></r>, <r v=\"Mark.11.15\"></r>, <r v=\"John.2.15\"></r> (cf. <g>κερματιοτής</g>).†</s>"},"G2892":{"l":"κουστωδία","o":3,"ar":"<f>*† <o>κουστωδία</o>، <g>-ας, ἡ</g>، (باللاتينية <l>custodia</l>)،</f> <s><b>حرّاس</b>: <r v=\"Matt.27.65\"></r>، <r v=\"Matt.27.66\"></r> <r v=\"Matt.28.11\"></r>.†</s>","en":"<f>*† <o>κουστωδία</o>, <g>-ας, ἡ</g>, (Lat. <l>custodia</l>),</f> <s><b>a guard</b>: <r v=\"Matt.27.65\"></r>, <r v=\"Matt.27.66\"></r> <r v=\"Matt.28.11\"></r>.†</s>"},"G2898":{"l":"κρανίον","o":4,"ar":"<f><o>κρανίον</o>، <g>-ου, τό</g></f> <s><b>جمجمة</b>: <r v=\"Matt.27.33\"></r>، <r v=\"Mark.15.22\"></r>، <r v=\"Luke.23.33\"></r>، <r v=\"John.19.17\"></r>.†</s>","en":"<f><o>κρανίον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>κάρα</g>, <i>the head</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Judg.9.53\"></r>, <r v=\"2Kgs.9.35\"></r> (<h n=\"H1538\">גֻּלְגֹּלֶת</h>)*;]</e> </et> <s><b>a skull</b>: <r v=\"Matt.27.33\"></r>, <r v=\"Mark.15.22\"></r>, <r v=\"Luke.23.33\"></r>, <r v=\"John.19.17\"></r>.†</s>"},"G2860":{"l":"κολυμβάω","o":1,"ar":"<f>** <o>κολυμβάω</o>، <g>-ῶ</g>،</f> <s><b>غطس</b>، <b>ألقى نفسه في البحر</b>: <r v=\"Acts.27.43\"></r> (قارن <g>ἐκ-κολνμβάω</g>).†</s>","en":"<f>** <o>κολυμβάω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in Al.: <r v=\"Isa.25.11\"></r>*;]</e> </et> <s><b>to dive</b>, <b>plunge into the sea</b>: <r v=\"Acts.27.43\"></r> (cf. <g>ἐκ-κολνμβάω</g>).†</s>"},"G2884":{"l":"κόρος","o":1,"ar":"<f><o>κόρος</o>، <g>-ου, ὁ</g></f> <s><b>كُرّ</b>، مكيال عبري (في الترجمة المعتمدة والمنقحة <i>مكيال</i>): <r v=\"Luke.16.7\"></r>.†</s>","en":"<f><o>κόρος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(Heb. <h n=\"H3734\">כֹּר</h>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Lev.27.16\"></r>, <r v=\"Num.11.32\"></r>, <r v=\"Ezek.45.13\"></r> (<h n=\"H2563\">חֹמֶר</h>); more freq., <r v=\"2Chr.27.5\"></r>, al.(<h n=\"H3734\">כֹּר</h>);]</e> </et> <s><b>a cor</b>, a Hebrew measure (AV, RV, <i>measure</i>): <r v=\"Luke.16.7\"></r>.†</s>"},"G2800":{"l":"κλάσις","o":13,"ar":"<f>* <o>κλάσις</o>، <g>-εως, ἡ</g></f> <s><b>كسر</b>: <r v=\"Luke.24.35\"></r>، <r v=\"Acts.2.42\"></r>.†</s>","en":"<f>* <o>κλάσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>κλάω</g>),</e> </et> <s><b>a breaking</b>: <r v=\"Luke.24.35\"></r>, <r v=\"Acts.2.42\"></r>.†</s>"},"G2829":{"l":"κλοπή","o":2,"ar":"<f>† <o>κλοπή</o>، <g>-ῆν, ἡ</g></f> <s><b>سرقة</b>: في الجمع، <r v=\"Matt.15.19\"></r>، <r v=\"Mark.7.22\"></r>.†</s>","en":"<f>† <o>κλοπή</o>, <g>-ῆν, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>κλέπτω</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H1589\">גּנב</h>;]</e> </et> <s><b>theft</b>: pl., <r v=\"Matt.15.19\"></r>, <r v=\"Mark.7.22\"></r>.†</s>"},"G2823":{"l":"κλίβανος","o":2,"ar":"<f><o>κλίβανος</o>، <g>-ον, ὁ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>كليبانوس</b>، <b>كريبانوس</b>، إناء فخاري لخبز الخبز.</s> <s n=\"2.\">في السبعينية والعهد الجديد، <b>أتون</b>، <b>تنّور</b>: <r v=\"Matt.6.30\"></r>، <r v=\"Luke.12.28\"></r>.†</s>","en":"<f><o>κλίβανος</o>, <g>-ον, ὁ</g></f> <et> <e t=\"derivation\">(Att., <g>κρίβ-</g>, but <g>κλ-</g> in Ion., Hdt., ii, 92),</e> <e t=\"septuagint\">[in LXX for <h n=\"H8574\">תַּנּוּר</h>, <r v=\"Gen.15.17\"></r>, <r v=\"Hos.7.4\"></r>, <r v=\"Hos.7.6\"></r> al.;]</e> </et> <s n=\"1.\">in cl., <b>a clibanus</b>, <b>cribanus</b>, an earthen vessel for baking bread.</s> <s n=\"2.\">In LXX and NT, <b>a furnace</b> (cf. MM, <i>Exp.</i>, xv), <b>an oven</b>: <r v=\"Matt.6.30\"></r>, <r v=\"Luke.12.28\"></r>.†</s>"},"G2869":{"l":"κοπάζω","o":3,"ar":"<f><o>κοπάζω</o></f> <s><b>تعب، كلّ</b>؛ وعن الريح (<r v=\"Jon.1.11\"></r>، <r v=\"Jon.1.12\"></r>)، <b>سكن</b>، <b>هدأ</b>: <r v=\"Matt.14.32\"></r>، <r v=\"Mark.4.39\"></r> <r v=\"Mark.6.51\"></r>.†</s>","en":"<f><o>κοπάζω</o></f> <et> <e t=\"derivation\">(&lt; <g>κόπος</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Gen.8.1\"></r>, <r v=\"Ezra.2.1\"></r> <r v=\"Ezra.7.10\"></r> (<h n=\"H7918\">שׁכךְ</h>), <r v=\"Ruth.1.18\"></r>, al. (<h n=\"H2308\">חדל</h>), <r v=\"Jon.1.11\"></r>, <r v=\"Jon.1.12\"></r> (<h n=\"H8367\">שׁתק</h>), al.;]</e> </et> <s><b>to grow weary</b>; of the wind (Hdt., <r v=\"Jon.1.11\"></r>, <r v=\"Jon.1.12\"></r>), <b>to abate</b>, <b>cease raging</b>: <r v=\"Matt.14.32\"></r>, <r v=\"Mark.4.39\"></r> <r v=\"Mark.6.51\"></r>.†</s>"},"G2867":{"l":"κονιάω","o":2,"ar":"<f><o>κονιάω</o>، <g>-ῶ</g></f> <s><b>طلى بالجير</b> أو <b>بيّض</b>: عن القبور، <r v=\"Matt.23.27\"></r>؛ مجازيًا، عن المرائي، <r v=\"Acts.23.3\"></r>.†</s>","en":"<f><o>κονιάω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>κονία</g>, <i>dust</i>, <b>lime</b>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Deut.27.2\"></r>, <r v=\"Deut.27.4\"></r> (<h n=\"H7874\">שִׂיד</h>), <r v=\"Prov.21.9\"></r>*;]</e> </et> <s><b>to plaster</b> or <b>whiten over</b>: of tombs, <r v=\"Matt.23.27\"></r>; fig., of a hypocrite, <r v=\"Acts.23.3\"></r>.†</s>"},"G2810":{"l":"Κλεόπας","o":1,"ar":"<f><o>Κλεόπας</o>، <g>-α</g>، <g>ὁ</g>،</f> <s><b>كليوباس</b>: <r v=\"Luke.24.18\"></r>.†</s>","en":"<f><o>Κλεόπας</o>, <g>-α</g> (v. Bl., § 7, 2), <g>ὁ</g>,</f> <s><b>Cleopas</b>: <r v=\"Luke.24.18\"></r>.†</s>"},"G2893":{"l":"κουφίζω","o":1,"ar":"<f><o>κουφίζω</o></f> <s n=\"1.\">في اليونانية الكلاسيكية (شعريًا غالبًا): لازم، <b>كان خفيفًا</b>.</s> <s n=\"2.\"><b>خفّف</b>، <b>جعله خفيفًا</b>: مع المنصوب، <r v=\"Acts.27.38\"></r>.†</s>","en":"<f><o>κουφίζω</o></f> <et> <e t=\"derivation\">(&lt; <g>κοῦφος</g>, <i>light</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Exod.18.22\"></r>, <r v=\"Jon.1.5\"></r>, al. (<h n=\"H7043\">קלל</h> hi.), <r v=\"Ezra.5.1\"></r>, al.;]</e> </et> <s n=\"1.\">intrans., <b>to be light</b> (poetic chiefly).</s> <s n=\"2.\"><b>to lighten</b>, <b>make light</b>: c. acc., <r v=\"Acts.27.38\"></r>.†</s>"},"G2874":{"l":"κοπρία","o":1,"ar":"<f><o>κοπρία</o>، <g>-ας, ἡ</g>،</f> <s><b>مزبلة</b> (<r v=\"1Sam.2.8\"></r>، <r v=\"Ps.113.7\"></r> وفي مواضع أخرى): <r v=\"Luke.14.35\"></r>.†</s>","en":"<f><o>κοπρία</o>, <g>-ας, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H830\">אַשְׁפֹּת</h>;]</e> </et> <s><b>a dung hill</b> (<r v=\"1Sam.2.8\"></r>, <r v=\"Ps.113.7\"></r> al.): <r v=\"Luke.14.35\"></r>.†</s>"},"G2838":{"l":"κοίμησις","o":1,"ar":"<f>** <o>κοίμησις</o>، <g>-εως, ἡ</g>،</f> <s><b>اضطجاع</b>، <b>راحة</b>: <r v=\"John.11.13\"></r>.†</s>","en":"<f>** <o>κοίμησις</o>, <g>-εως, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Sir.46.19\"></r> <r v=\"Sir.48.13\"></r>*;]</e> </et> <s><b>a reclining</b>, <b>resting</b>: <r v=\"John.11.13\"></r>.†</s>"},"G2859":{"l":"κόλπος","o":6,"ar":"<f><o>κόλπος</o>، <g>-ου, ὁ</g>،</f> <s n=\"1.\">حرفيًا، <b>الحضن</b>: <r v=\"John.13.23\"></r>؛ مجازيًا، عن الصلة الوثيقة، <g>ἐν</g> (<g>εἰς τὸν</g>) <g>τοῖς κ. Ἀβραάμ</g>، <r v=\"Luke.16.22\"></r>، <r v=\"Luke.16.23\"></r> (قارن <r v=\"4Macc.13.16\"></r>)؛ <g>ὁ ὢν εἰς τὸν κ. τ. πατρός</g>، <r v=\"John.1.18\"></r>.</s> <s n=\"2.\"><b>حِضن</b> الثوب الفضفاض أو ثنيته المتدلية فوق المنطقة، تُستعمل جيبًا، ومن ثم مجازيًا، <g>εἰς τὸν κ.</g> (<r v=\"Isa.65.6\"></r>، <r v=\"Jer.32.18\"></r>): <r v=\"Luke.6.38\"></r>.</s> <s n=\"3.\">تجويف يشبه الحضن، مثل <b>الخليج</b> أو <b>الجون</b>: <r v=\"Acts.27.39\"></r>.†</s>","en":"<f><o>κόλπος</o>, <g>-ου, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2436\">חֵיק</h>, <h n=\"H2436\">חוֹק</h>, <h n=\"H2436\">חֵק</h>;]</e> </et> <s n=\"1.\">prop., <b>the bosom</b>: <r v=\"John.13.23\"></r>; fig., of close association, <g>ἐν</g> (<g>εἰς τὸν</g>) <g>τοῖς κ. Ἀβραάμ</g>, <r v=\"Luke.16.22\"></r>, <r v=\"Luke.16.23\"></r> (cf. <r v=\"4Macc.13.16\"></r>); <g>ὁ ὢν εἰς τὸν κ. τ. πατρός</g>, <r v=\"John.1.18\"></r>.</s> <s n=\"2.\">The <b>bosom</b> or fold of a loose garment falling over a girdle, used as a pocket, hence fig., <g>εἰς τὸν κ.</g> (<r v=\"Isa.65.6\"></r>, <r v=\"Jer.32.18\"></r>): <r v=\"Luke.6.38\"></r>.</s> <s n=\"3.\">A bosom-like hollow, as a <b>bay</b> or <b>gulf</b>: <r v=\"Acts.27.39\"></r>.†</s>"},"G2861":{"l":"κολυμβήθρα","o":3,"ar":"<f><o>κολυμβήθρα</o>، <g>-ας, ἡ</g></f> <s><b>حوض سباحة</b>، <b>بِركة</b>: <r v=\"John.5.2\"></r>، [<r v=\"John.5.4\"></r>]، <r v=\"John.5.7\"></r>، <r v=\"John.9.7\"></r>.†</s>","en":"<f><o>κολυμβήθρα</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>κολυμβάω</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H1295\">בְּרֵכָה</h>, <r v=\"2Kgs.18.27\"></r>, al.;]</e> </et> <s><b>a swimming pool</b>, <b>pool</b>: <r v=\"John.5.2\"></r>, [<r v=\"John.5.4\"></r>], <r v=\"John.5.7\"></r> <r v=\"John.9.7\"></r>.†</s>"},"G2862":{"l":"κολωνία","o":1,"ar":"<f>*† <o>κολωνία</o>، <g>-ας, ἡ</g></f> <s><b>مستعمرة (كولونية)</b>: <r v=\"Acts.16.12\"></r>.†</s>","en":"<f>*† <o>κολωνία</o>, (Rec. <g>-ώνια</g>), <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; Lat. <l>colonia</l>),</e> </et> <s><b>a colony</b>: <r v=\"Acts.16.12\"></r> (v. Lft., <i>Phi.</i>, 50 f.).†</s>"}});A.got[28]=1})(window.ABBOTT=window.ABBOTT||{D:{},got:{}});